/**
 * Environment configuration module
 * Handles environment variable loading and type-safe access
 */

import { z } from 'zod';

/**
 * Environment variable schema with validation
 */
const EnvSchema = z.object({
  NODE_ENV: z.enum(['development', 'production', 'test']).default('production'),
  IS_DOCKER_ENVIRONMENT: z
    .string()
    .optional()
    .transform((val) => val === 'true'),
  MOARTUBE_DATA_DIR: z.string().optional(),
  DATABASE_URL: z.string().optional(),
  LOG_LEVEL: z.enum(['error', 'warn', 'info', 'debug', 'trace']).default('info'),
  PORT: z
    .string()
    .optional()
    .transform((val) => (val ? parseInt(val, 10) : undefined)),
  HOST: z.string().optional(),
});

/**
 * Parsed environment configuration type
 */
export type EnvConfig = z.infer<typeof EnvSchema>;

/**
 * Environment configuration singleton
 */
class Env {
  private static instance: Env;
  private config: EnvConfig;

  private constructor() {
    this.config = this.loadAndValidate();
  }

  /**
   * Get the singleton instance
   */
  static getInstance(): Env {
    if (!Env.instance) {
      Env.instance = new Env();
    }
    return Env.instance;
  }

  /**
   * Load and validate environment variables
   */
  private loadAndValidate(): EnvConfig {
    const result = EnvSchema.safeParse({
      NODE_ENV: process.env['NODE_ENV'],
      IS_DOCKER_ENVIRONMENT: process.env['IS_DOCKER_ENVIRONMENT'],
      MOARTUBE_DATA_DIR: process.env['MOARTUBE_DATA_DIR'],
      DATABASE_URL: process.env['DATABASE_URL'],
      LOG_LEVEL: process.env['LOG_LEVEL'],
      PORT: process.env['PORT'],
      HOST: process.env['HOST'],
    });

    if (!result.success) {
      throw new Error(`Invalid environment configuration: ${result.error.message}`);
    }

    return result.data;
  }

  /**
   * Get all environment configuration
   */
  getAll(): Readonly<EnvConfig> {
    return Object.freeze({ ...this.config });
  }

  /**
   * Check if running in development mode
   */
  get isDevelopment(): boolean {
    return this.config.NODE_ENV === 'development';
  }

  /**
   * Check if running in production mode
   */
  get isProduction(): boolean {
    return this.config.NODE_ENV === 'production';
  }

  /**
   * Check if running in test mode
   */
  get isTest(): boolean {
    return this.config.NODE_ENV === 'test';
  }

  /**
   * Check if running in Docker environment
   */
  get isDockerEnvironment(): boolean {
    return this.config.IS_DOCKER_ENVIRONMENT;
  }

  /**
   * Get the data directory path from environment
   */
  get dataDirectory(): string | undefined {
    return this.config.MOARTUBE_DATA_DIR;
  }

  /**
   * Get the database URL from environment
   */
  get databaseUrl(): string | undefined {
    return this.config.DATABASE_URL;
  }

  /**
   * Get the log level
   */
  get logLevel(): EnvConfig['LOG_LEVEL'] {
    return this.config.LOG_LEVEL;
  }

  /**
   * Get the port from environment
   */
  get port(): number | undefined {
    return this.config.PORT;
  }

  /**
   * Get the host from environment
   */
  get host(): string | undefined {
    return this.config.HOST;
  }

  /**
   * Get the current NODE_ENV
   */
  get nodeEnv(): EnvConfig['NODE_ENV'] {
    return this.config.NODE_ENV;
  }
}

/**
 * Export singleton instance getter
 */
export function getEnv(): Env {
  return Env.getInstance();
}

/**
 * Export the Env class for testing purposes
 */
export { Env };

/**
 * Path configuration module
 * Centralized management of all file and directory paths used by the application
 */

import path from 'node:path';
import { getEnv } from './env.js';

/**
 * Path configuration interface
 */
export interface PathConfig {
  // Base directories
  readonly publicDirectoryPath: string;
  readonly dataDirectoryPath: string;
  readonly viewsDirectoryPath: string;

  // Data subdirectories
  readonly imagesDirectoryPath: string;
  readonly videosDirectoryPath: string;
  readonly databaseDirectoryPath: string;
  readonly certificatesDirectoryPath: string;

  // Config files
  readonly nodeSettingsPath: string;
  readonly nodeIdentificationPath: string;
  readonly lastCheckedContentTrackerPath: string;
  readonly databaseFilePath: string;
}

/**
 * Path configuration singleton class
 */
class Paths implements PathConfig {
  private static instance: Paths;

  // Base directories
  readonly publicDirectoryPath: string;
  readonly dataDirectoryPath: string;
  readonly viewsDirectoryPath: string;

  // Data subdirectories
  readonly imagesDirectoryPath: string;
  readonly videosDirectoryPath: string;
  readonly databaseDirectoryPath: string;
  readonly certificatesDirectoryPath: string;

  // Config files
  readonly nodeSettingsPath: string;
  readonly nodeIdentificationPath: string;
  readonly lastCheckedContentTrackerPath: string;
  readonly databaseFilePath: string;

  private constructor(baseDir: string) {
    const env = getEnv();
    const isDocker = env.isDockerEnvironment;

    // Base directories
    this.publicDirectoryPath = path.join(baseDir, 'public');
    this.viewsDirectoryPath = path.join(this.publicDirectoryPath, 'views');

    // Data directory - use environment variable if set, otherwise use default
    const dataDir = env.dataDirectory ?? path.join(baseDir, 'data');
    this.dataDirectoryPath = isDocker ? '/data' : dataDir;

    // Data subdirectories
    this.imagesDirectoryPath = path.join(this.dataDirectoryPath, 'images');
    this.videosDirectoryPath = path.join(this.dataDirectoryPath, 'media', 'videos');
    this.databaseDirectoryPath = path.join(this.dataDirectoryPath, 'db');
    this.certificatesDirectoryPath = path.join(this.dataDirectoryPath, 'certificates');

    // Config files
    this.nodeSettingsPath = path.join(this.dataDirectoryPath, '_node_settings.json');
    this.nodeIdentificationPath = path.join(this.dataDirectoryPath, '_node_identification.json');
    this.lastCheckedContentTrackerPath = path.join(
      this.dataDirectoryPath,
      '_last_checked_content_tracker.json'
    );
    this.databaseFilePath = path.join(this.databaseDirectoryPath, 'node_db.sqlite');
  }

  /**
   * Initialize the paths singleton with the application base directory
   */
  static initialize(baseDir: string): Paths {
    if (!Paths.instance) {
      Paths.instance = new Paths(baseDir);
    }
    return Paths.instance;
  }

  /**
   * Get the singleton instance
   * @throws Error if not initialized
   */
  static getInstance(): Paths {
    if (!Paths.instance) {
      throw new Error('Paths not initialized. Call Paths.initialize(baseDir) first.');
    }
    return Paths.instance;
  }

  /**
   * Check if the paths have been initialized
   */
  static isInitialized(): boolean {
    return Paths.instance !== undefined;
  }

  /**
   * Get video directory path for a specific video
   */
  getVideoDirectoryPath(videoId: string): string {
    return path.join(this.videosDirectoryPath, videoId);
  }

  /**
   * Get video images directory path for a specific video
   */
  getVideoImagesDirectoryPath(videoId: string): string {
    return path.join(this.getVideoDirectoryPath(videoId), 'images');
  }

  /**
   * Get video adaptive directory path for a specific video
   */
  getVideoAdaptiveDirectoryPath(videoId: string): string {
    return path.join(this.getVideoDirectoryPath(videoId), 'adaptive');
  }

  /**
   * Get video progressive directory path for a specific video
   */
  getVideoProgressiveDirectoryPath(videoId: string): string {
    return path.join(this.getVideoDirectoryPath(videoId), 'progressive');
  }

  /**
   * Get thumbnail image path for a specific video
   */
  getVideoThumbnailPath(videoId: string): string {
    return path.join(this.getVideoImagesDirectoryPath(videoId), 'thumbnail.jpg');
  }

  /**
   * Get preview image path for a specific video
   */
  getVideoPreviewPath(videoId: string): string {
    return path.join(this.getVideoImagesDirectoryPath(videoId), 'preview.jpg');
  }

  /**
   * Get poster image path for a specific video
   */
  getVideoPosterPath(videoId: string): string {
    return path.join(this.getVideoImagesDirectoryPath(videoId), 'poster.jpg');
  }

  /**
   * Get custom icon path (data/images/icon.png)
   */
  getCustomIconPath(): string {
    return path.join(this.imagesDirectoryPath, 'icon.png');
  }

  /**
   * Get default icon path (public/images/icon.png)
   */
  getDefaultIconPath(): string {
    return path.join(this.publicDirectoryPath, 'images', 'icon.png');
  }

  /**
   * Get custom avatar path (data/images/avatar.png)
   */
  getCustomAvatarPath(): string {
    return path.join(this.imagesDirectoryPath, 'avatar.png');
  }

  /**
   * Get default avatar path (public/images/avatar.png)
   */
  getDefaultAvatarPath(): string {
    return path.join(this.publicDirectoryPath, 'images', 'avatar.png');
  }

  /**
   * Get custom banner path (data/images/banner.png)
   */
  getCustomBannerPath(): string {
    return path.join(this.imagesDirectoryPath, 'banner.png');
  }

  /**
   * Get default banner path (public/images/banner.png)
   */
  getDefaultBannerPath(): string {
    return path.join(this.publicDirectoryPath, 'images', 'banner.png');
  }

  /**
   * Get all paths as a plain object
   */
  toObject(): PathConfig {
    return {
      publicDirectoryPath: this.publicDirectoryPath,
      dataDirectoryPath: this.dataDirectoryPath,
      viewsDirectoryPath: this.viewsDirectoryPath,
      imagesDirectoryPath: this.imagesDirectoryPath,
      videosDirectoryPath: this.videosDirectoryPath,
      databaseDirectoryPath: this.databaseDirectoryPath,
      certificatesDirectoryPath: this.certificatesDirectoryPath,
      nodeSettingsPath: this.nodeSettingsPath,
      nodeIdentificationPath: this.nodeIdentificationPath,
      lastCheckedContentTrackerPath: this.lastCheckedContentTrackerPath,
      databaseFilePath: this.databaseFilePath,
    };
  }
}

/**
 * Export singleton instance getter
 */
export function getPaths(): Paths {
  return Paths.getInstance();
}

/**
 * Export initializer
 */
export function initializePaths(baseDir: string): Paths {
  return Paths.initialize(baseDir);
}

/**
 * Export the Paths class for testing purposes
 */
export { Paths };

/**
 * Configuration schema validation module
 * Zod schemas for runtime validation of all configuration structures
 */

import { z } from 'zod';

// ============================================
// Database Configuration Schemas
// ============================================

/**
 * PostgreSQL configuration schema
 */
export const PostgresConfigSchema = z.object({
  databaseName: z.string().min(1, 'Database name is required'),
  username: z.string().min(1, 'Username is required'),
  password: z.string(),
  host: z.string().min(1, 'Host is required'),
  port: z.number().int().min(1).max(65535).default(5432),
});

/**
 * Database configuration schema
 */
export const DatabaseConfigSchema = z.object({
  databaseDialect: z.enum(['sqlite', 'postgres']),
  postgresConfig: PostgresConfigSchema.optional(),
});

// ============================================
// S3 Storage Configuration Schemas
// ============================================

/**
 * S3 credentials schema
 */
export const S3CredentialsSchema = z.object({
  accessKeyId: z.string().min(1, 'Access key ID is required'),
  secretAccessKey: z.string().min(1, 'Secret access key is required'),
});

/**
 * S3 provider client configuration schema
 */
export const S3ProviderClientConfigSchema = z.object({
  forcePathStyle: z.boolean().default(false),
  region: z.string().min(1, 'Region is required'),
  credentials: S3CredentialsSchema,
  endpoint: z.string().url().optional(),
});

/**
 * S3 configuration schema
 */
export const S3ConfigSchema = z.object({
  bucketName: z.string().min(1, 'Bucket name is required'),
  s3ProviderClientConfig: S3ProviderClientConfigSchema,
});

/**
 * Storage configuration schema
 */
export const StorageConfigSchema = z.object({
  storageMode: z.enum(['filesystem', 's3provider']),
  s3Config: S3ConfigSchema.optional(),
});

// ============================================
// Node Settings Schema
// ============================================

/**
 * Complete node settings schema with all fields validated
 */
export const NodeSettingsSchema = z.object({
  // Server Configuration
  nodeListeningPort: z.union([z.number(), z.string()]).transform((val) => {
    const num = typeof val === 'string' ? parseInt(val, 10) : val;
    if (isNaN(num) || num < 1 || num > 65535) {
      throw new Error('Port must be between 1 and 65535');
    }
    return num;
  }),
  isSecure: z.boolean().default(false),
  publicNodeProtocol: z.enum(['http', 'https', '']).default(''),
  publicNodeAddress: z.string().default(''),
  publicNodePort: z.union([z.number(), z.string()]).default(''),

  // Node Identity
  nodeName: z.string().default('MoarTube Node'),
  nodeAbout: z.string().default('A MoarTube Node'),
  nodeId: z.string().min(1, 'Node ID is required'),

  // Authentication (Base64 encoded bcrypt hashes)
  username: z.string().min(1, 'Username hash is required'),
  password: z.string().min(1, 'Password hash is required'),
  expressSessionName: z.string().min(1, 'Session name is required'),
  expressSessionSecret: z.string().min(1, 'Session secret is required'),

  // Cloudflare Settings
  isCloudflareCdnEnabled: z.boolean().default(false),
  cloudflareEmailAddress: z.string().default(''),
  cloudflareZoneId: z.string().default(''),
  cloudflareGlobalApiKey: z.string().default(''),
  isCloudflareTurnstileEnabled: z.boolean().default(false),
  cloudflareTurnstileSiteKey: z.string().default(''),
  cloudflareTurnstileSecretKey: z.string().default(''),

  // Feature Flags
  isCommentsEnabled: z.boolean().default(true),
  isLikesEnabled: z.boolean().default(true),
  isDislikesEnabled: z.boolean().default(true),
  isReportsEnabled: z.boolean().default(true),
  isLiveChatEnabled: z.boolean().default(true),

  // Database & Storage
  databaseConfig: DatabaseConfigSchema,
  storageConfig: StorageConfigSchema,

  // Optional external videos base URL
  externalVideosBaseUrl: z.string().optional(),
});

// ============================================
// App Config Schemas
// ============================================

/**
 * Indexer service configuration schema
 */
export const IndexerConfigSchema = z.object({
  httpProtocol: z.enum(['http', 'https']),
  host: z.string().min(1, 'Indexer host is required'),
  port: z.number().int().min(1).max(65535),
});

/**
 * Aliaser service configuration schema
 */
export const AliaserConfigSchema = z.object({
  httpProtocol: z.enum(['http', 'https']),
  host: z.string().min(1, 'Aliaser host is required'),
  port: z.number().int().min(1).max(65535),
});

/**
 * Main application config schema (config.json)
 */
export const AppConfigSchema = z.object({
  isDeveloperMode: z.boolean().default(false),
  indexerConfig: IndexerConfigSchema,
  aliaserConfig: AliaserConfigSchema,
});

// ============================================
// Node Identification Schema
// ============================================

/**
 * Node identification schema
 */
export const NodeIdentificationSchema = z.object({
  moarTubeTokenProof: z.string(),
});

// ============================================
// Last Checked Content Tracker Schema
// ============================================

/**
 * Content tracker schema
 */
export const LastCheckedContentTrackerSchema = z.object({
  lastCheckedCommentsTimestamp: z.number().default(0),
  lastCheckedVideoReportsTimestamp: z.number().default(0),
  lastCheckedCommentReportsTimestamp: z.number().default(0),
});

// ============================================
// Inferred Types (for runtime use)
// ============================================

export type PostgresConfigValidated = z.infer<typeof PostgresConfigSchema>;
export type DatabaseConfigValidated = z.infer<typeof DatabaseConfigSchema>;
export type S3ConfigValidated = z.infer<typeof S3ConfigSchema>;
export type StorageConfigValidated = z.infer<typeof StorageConfigSchema>;
export type NodeSettingsValidated = z.infer<typeof NodeSettingsSchema>;
export type AppConfigValidated = z.infer<typeof AppConfigSchema>;
export type NodeIdentificationValidated = z.infer<typeof NodeIdentificationSchema>;
export type LastCheckedContentTrackerValidated = z.infer<typeof LastCheckedContentTrackerSchema>;

// ============================================
// Validation Helper Functions
// ============================================

/**
 * Validate node settings with detailed error messages
 */
export function validateNodeSettings(data: unknown): NodeSettingsValidated {
  const result = NodeSettingsSchema.safeParse(data);
  if (!result.success) {
    throw new Error(`Invalid node settings: ${result.error.message}`);
  }
  return result.data;
}

/**
 * Validate app config with detailed error messages
 */
export function validateAppConfig(data: unknown): AppConfigValidated {
  const result = AppConfigSchema.safeParse(data);
  if (!result.success) {
    throw new Error(`Invalid app config: ${result.error.message}`);
  }
  return result.data;
}

/**
 * Validate node identification
 */
export function validateNodeIdentification(data: unknown): NodeIdentificationValidated {
  const result = NodeIdentificationSchema.safeParse(data);
  if (!result.success) {
    throw new Error(`Invalid node identification: ${result.error.message}`);
  }
  return result.data;
}

/**
 * Validate last checked content tracker
 */
export function validateLastCheckedContentTracker(
  data: unknown
): LastCheckedContentTrackerValidated {
  const result = LastCheckedContentTrackerSchema.safeParse(data);
  if (!result.success) {
    throw new Error(`Invalid content tracker: ${result.error.message}`);
  }
  return result.data;
}

/**
 * Safely parse node settings (returns null on failure)
 */
export function safeParseNodeSettings(data: unknown): NodeSettingsValidated | null {
  const result = NodeSettingsSchema.safeParse(data);
  return result.success ? result.data : null;
}

/**
 * Safely parse app config (returns null on failure)
 */
export function safeParseAppConfig(data: unknown): AppConfigValidated | null {
  const result = AppConfigSchema.safeParse(data);
  return result.success ? result.data : null;
}

/**
 * URL configuration module
 * Centralized management of all external service URLs
 */

import { z } from 'zod';
import type { IndexerConfig, AliaserConfig, NodeSettings, StorageConfig } from '../types/index.js';

/**
 * Service endpoint configuration schema
 */
const ServiceEndpointSchema = z.object({
  httpProtocol: z.enum(['http', 'https']),
  host: z.string().min(1),
  port: z.number().int().min(1).max(65535),
});

/**
 * URL configuration interface
 */
export interface UrlConfig {
  readonly indexerUrl: string;
  readonly aliaserUrl: string;
  readonly cloudflareZoneUrl: string;
}

/**
 * URL configuration singleton class
 */
class Urls {
  private static instance: Urls;

  private indexerConfig: IndexerConfig;
  private aliaserConfig: AliaserConfig;

  private constructor(indexerConfig: IndexerConfig, aliaserConfig: AliaserConfig) {
    // Validate configs
    const indexerResult = ServiceEndpointSchema.safeParse(indexerConfig);
    if (!indexerResult.success) {
      throw new Error(`Invalid indexer config: ${indexerResult.error.message}`);
    }

    const aliaserResult = ServiceEndpointSchema.safeParse(aliaserConfig);
    if (!aliaserResult.success) {
      throw new Error(`Invalid aliaser config: ${aliaserResult.error.message}`);
    }

    this.indexerConfig = indexerConfig;
    this.aliaserConfig = aliaserConfig;
  }

  /**
   * Initialize the URLs singleton with service configurations
   */
  static initialize(indexerConfig: IndexerConfig, aliaserConfig: AliaserConfig): Urls {
    if (!Urls.instance) {
      Urls.instance = new Urls(indexerConfig, aliaserConfig);
    }
    return Urls.instance;
  }

  /**
   * Get the singleton instance
   * @throws Error if not initialized
   */
  static getInstance(): Urls {
    if (!Urls.instance) {
      throw new Error('Urls not initialized. Call Urls.initialize() first.');
    }
    return Urls.instance;
  }

  /**
   * Check if URLs have been initialized
   */
  static isInitialized(): boolean {
    return Urls.instance !== undefined;
  }

  /**
   * Get the MoarTube Indexer URL
   */
  get indexerUrl(): string {
    const { httpProtocol, host, port } = this.indexerConfig;
    return this.buildUrl(httpProtocol, host, port);
  }

  /**
   * Get the MoarTube Aliaser URL
   */
  get aliaserUrl(): string {
    const { httpProtocol, host, port } = this.aliaserConfig;
    return this.buildUrl(httpProtocol, host, port);
  }

  /**
   * Get the Cloudflare Zone API URL
   */
  get cloudflareZoneUrl(): string {
    return 'https://api.cloudflare.com/client/v4/zones/';
  }

  /**
   * Get indexer config details
   */
  getIndexerConfig(): Readonly<IndexerConfig> {
    return Object.freeze({ ...this.indexerConfig });
  }

  /**
   * Get aliaser config details
   */
  getAliaserConfig(): Readonly<AliaserConfig> {
    return Object.freeze({ ...this.aliaserConfig });
  }

  /**
   * Build a URL from protocol, host, and port
   */
  private buildUrl(protocol: string, host: string, port: number): string {
    // Omit default ports
    const portSuffix =
      (protocol === 'http' && port === 80) || (protocol === 'https' && port === 443)
        ? ''
        : `:${port}`;
    return `${protocol}://${host}${portSuffix}`;
  }

  /**
   * Get all URLs as a plain object
   */
  toObject(): UrlConfig {
    return {
      indexerUrl: this.indexerUrl,
      aliaserUrl: this.aliaserUrl,
      cloudflareZoneUrl: this.cloudflareZoneUrl,
    };
  }
}

/**
 * Build the node's public base URL from node settings
 */
export function buildNodeBaseUrl(nodeSettings: NodeSettings): string {
  const { publicNodeProtocol, publicNodeAddress, publicNodePort } = nodeSettings;

  if (!publicNodeProtocol || !publicNodeAddress) {
    throw new Error('Node public protocol and address must be configured');
  }

  const port = typeof publicNodePort === 'string' ? parseInt(publicNodePort, 10) : publicNodePort;

  // Omit default ports
  let portSuffix = '';
  if (publicNodeProtocol === 'http' && port !== 80) {
    portSuffix = `:${port}`;
  } else if (publicNodeProtocol === 'https' && port !== 443) {
    portSuffix = `:${port}`;
  }

  return `${publicNodeProtocol}://${publicNodeAddress}${portSuffix}`;
}

/**
 * Build the external videos base URL based on storage configuration
 */
export function buildExternalVideosBaseUrl(nodeSettings: NodeSettings): string {
  const { storageConfig, isCloudflareCdnEnabled } = nodeSettings;

  if (storageConfig.storageMode === 'filesystem') {
    return buildNodeBaseUrl(nodeSettings);
  }

  // S3 provider mode
  return buildS3ExternalUrl(storageConfig, isCloudflareCdnEnabled);
}

/**
 * Build S3 external URL based on configuration
 */
function buildS3ExternalUrl(storageConfig: StorageConfig, isCloudflareCdnEnabled: boolean): string {
  if (storageConfig.storageMode !== 's3provider' || !storageConfig.s3Config) {
    throw new Error('S3 config required for s3provider storage mode');
  }

  const { bucketName, s3ProviderClientConfig } = storageConfig.s3Config;
  const { endpoint, region, forcePathStyle } = s3ProviderClientConfig;

  // If Cloudflare CDN is enabled, use bucket name as subdomain
  if (isCloudflareCdnEnabled) {
    return `https://${bucketName}`;
  }

  // Custom endpoint (non-AWS S3 provider)
  if (endpoint) {
    if (forcePathStyle) {
      // Path-style: endpoint/bucket
      return `${endpoint}/${bucketName}`;
    } else {
      // Virtual-hosted style: bucket.endpoint
      const protocolMatch = endpoint.match(/^(https?:\/\/)(.*)/);
      if (!protocolMatch?.[1] || !protocolMatch[2]) {
        throw new Error(`Invalid S3 endpoint format: ${endpoint}`);
      }

      const protocol = protocolMatch[1];
      const hostAndPort = protocolMatch[2];
      const colonIndex = hostAndPort.indexOf(':');

      if (colonIndex !== -1) {
        const host = hostAndPort.slice(0, colonIndex);
        const port = hostAndPort.slice(colonIndex + 1);
        return `${protocol}${bucketName}.${host}:${port}`;
      } else {
        return `${protocol}${bucketName}.${hostAndPort}`;
      }
    }
  }

  // AWS S3 (no custom endpoint)
  if (forcePathStyle) {
    // Path-style AWS URL
    return `https://s3.${region}.amazonaws.com/${bucketName}`;
  } else {
    // Virtual-hosted style AWS URL
    return `http://${bucketName}.s3.${region}.amazonaws.com`;
  }
}

/**
 * Build the external resources base URL (always uses node URL)
 */
export function buildExternalResourcesBaseUrl(nodeSettings: NodeSettings): string {
  return buildNodeBaseUrl(nodeSettings);
}

/**
 * Export singleton instance getter
 */
export function getUrls(): Urls {
  return Urls.getInstance();
}

/**
 * Export initializer
 */
export function initializeUrls(indexerConfig: IndexerConfig, aliaserConfig: AliaserConfig): Urls {
  return Urls.initialize(indexerConfig, aliaserConfig);
}

/**
 * Export the Urls class for testing purposes
 */
export { Urls };

