/**
 * Base Controller
 *
 * Abstract base class providing common functionality for all controllers.
 * Includes standardized response methods and error handling.
 */
import type { FastifyReply } from 'fastify';
import { Logger, type ILogger } from '../utils/logger.js';

/**
 * Standard API success response
 */
export interface ApiSuccessResponse<T = unknown> {
  isError: false;
  data?: T;
  [key: string]: unknown;
}

/**
 * Standard API error response
 */
export interface ApiErrorResponse {
  isError: true;
  message: string;
}

/**
 * Paginated response wrapper
 */
export interface PaginatedResponse<T> {
  isError: false;
  data: T[];
  pagination: {
    total: number;
    page: number;
    limit: number;
    pages: number;
    hasMore: boolean;
  };
}

/**
 * Base controller class
 *
 * Provides utility methods for sending consistent API responses.
 * All controllers should extend this class.
 */
export abstract class BaseController {
  /**
   * Controller name for logging
   */
  protected readonly controllerName: string;

  /**
   * Logger instance for the controller
   */
  protected readonly logger: ILogger;

  constructor(name: string) {
    this.controllerName = name;
    this.logger = new Logger({ prefix: name });
  }

  /**
   * Send a success response with data
   *
   * @param reply - Fastify reply object
   * @param data - Response data
   * @param messageOrStatus - Optional message string or HTTP status code (default: 200)
   */
  protected sendSuccess<T>(
    reply: FastifyReply,
    data: T,
    messageOrStatus: string | number = 200
  ): void {
    const status = typeof messageOrStatus === 'number' ? messageOrStatus : 200;
    const response = { isError: false as const, ...data };
    void reply.status(status).send(response);
  }

  /**
   * Send a success response without additional data
   *
   * @param reply - Fastify reply object
   * @param status - HTTP status code (default: 200)
   */
  protected sendOk(reply: FastifyReply, status = 200): void {
    void reply.status(status).send({ isError: false });
  }

  /**
   * Send an error response
   *
   * @param reply - Fastify reply object
   * @param message - Error message
   * @param status - HTTP status code (default: 400)
   */
  protected sendError(reply: FastifyReply, message: string, status = 400): void {
    void reply.status(status).send({ isError: true, message });
  }

  /**
   * Send a paginated response
   *
   * @param reply - Fastify reply object
   * @param data - Array of items
   * @param total - Total count (before pagination)
   * @param page - Current page (1-indexed)
   * @param limit - Items per page
   */
  protected sendPaginated<T>(
    reply: FastifyReply,
    data: T[],
    total: number,
    page: number,
    limit: number
  ): void {
    const pages = Math.ceil(total / limit);
    const hasMore = page < pages;

    const response: PaginatedResponse<T> = {
      isError: false,
      data,
      pagination: {
        total,
        page,
        limit,
        pages,
        hasMore,
      },
    };

    void reply.send(response);
  }

  /**
   * Send raw data (for compatibility with existing API)
   *
   * @param reply - Fastify reply object
   * @param data - Raw data to send
   * @param status - HTTP status code (default: 200)
   */
  protected sendRaw(reply: FastifyReply, data: unknown, status = 200): void {
    void reply.status(status).send(data);
  }
}

/**
 * External Videos Controller
 *
 * Handles serving video content (thumbnails, previews, posters, adaptive streams, progressive downloads).
 */
import type { FastifyRequest, FastifyReply } from 'fastify';
import fs from 'node:fs';
import path from 'node:path';
import { BaseController } from './base.js';
import type { VideosRepository } from '../database/repositories/videos.js';
import { getConfig } from '../config/index.js';
import {
  isVideoIdValid,
  isAdaptiveFormatValid,
  isProgressiveFormatValid,
  isResolutionValid,
  isManifestNameValid,
  isSegmentNameValid,
  isManifestTypeValid,
  isProgressiveFilenameValid,
} from '../utils/index.js';

/**
 * Route params for video images
 */
interface VideoIdParams {
  videoId: string;
}

/**
 * Route params for adaptive manifests
 */
interface AdaptiveManifestParams {
  videoId: string;
  format: string;
  type: string;
  manifestName: string;
}

/**
 * Route params for adaptive segments
 */
interface AdaptiveSegmentParams {
  videoId: string;
  format: string;
  resolution: string;
  segmentName: string;
}

/**
 * Route params for progressive files
 */
interface ProgressiveParams {
  videoId: string;
  format: string;
  progressiveFilename: string;
}

/**
 * ExternalVideosController class
 *
 * Handles:
 * - Get external videos base URL
 * - Serve video thumbnail images
 * - Serve video preview images
 * - Serve video poster images
 * - Serve HLS/DASH manifests
 * - Serve HLS/DASH segments
 * - Serve progressive video files (with range support)
 */
export class ExternalVideosController extends BaseController {
  // Bandwidth tracking state
  private segmentBandwidthCounter = 0;
  private segmentBandwidthTimer: ReturnType<typeof setTimeout> | null = null;
  private progressiveBandwidthCounter = 0;
  private progressiveBandwidthTimer: ReturnType<typeof setTimeout> | null = null;

  constructor(private readonly videoRepository: VideosRepository) {
    super('ExternalVideosController');
  }

  /**
   * GET /external/videos/baseUrl
   *
   * Get external videos base URL
   */
  getBaseUrl = async (_request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const config = getConfig();
      const externalVideosBaseUrl = config.getExternalVideosBaseUrl();

      this.sendSuccess(reply, { externalVideosBaseUrl });
    } catch (error) {
      this.logger.error('Get base URL failed', error instanceof Error ? error : null);
      this.sendError(reply, 'error communicating with the MoarTube node');
    }
  };

  /**
   * GET /external/videos/:videoId/images/thumbnail.jpg
   *
   * Serve video thumbnail image
   */
  getThumbnail = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId } = request.params as VideoIdParams;

      if (!isVideoIdValid(videoId, false)) {
        void reply.status(404).send('thumbnail not found');
        return;
      }

      const config = getConfig();
      const thumbnailPath = path.join(
        config.paths.videosDirectoryPath,
        videoId,
        'images',
        'thumbnail.jpg'
      );

      if (!fs.existsSync(thumbnailPath)) {
        void reply.status(404).send('thumbnail not found');
        return;
      }

      const fileStream = fs.createReadStream(thumbnailPath);
      void reply.header('Content-Type', 'image/jpeg').send(fileStream);
    } catch (error) {
      this.logger.error('Get thumbnail failed', error instanceof Error ? error : null);
      void reply.status(404).send('thumbnail not found');
    }
  };

  /**
   * GET /external/videos/:videoId/images/preview.jpg
   *
   * Serve video preview image
   */
  getPreview = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId } = request.params as VideoIdParams;

      if (!isVideoIdValid(videoId, false)) {
        void reply.status(404).send('preview not found');
        return;
      }

      const config = getConfig();
      const previewPath = path.join(
        config.paths.videosDirectoryPath,
        videoId,
        'images',
        'preview.jpg'
      );

      if (!fs.existsSync(previewPath)) {
        void reply.status(404).send('preview not found');
        return;
      }

      const fileStream = fs.createReadStream(previewPath);
      void reply.header('Content-Type', 'image/jpeg').send(fileStream);
    } catch (error) {
      this.logger.error('Get preview failed', error instanceof Error ? error : null);
      void reply.status(404).send('preview not found');
    }
  };

  /**
   * GET /external/videos/:videoId/images/poster.jpg
   *
   * Serve video poster image
   */
  getPoster = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId } = request.params as VideoIdParams;

      if (!isVideoIdValid(videoId, false)) {
        void reply.status(404).send('poster not found');
        return;
      }

      const config = getConfig();
      const posterPath = path.join(
        config.paths.videosDirectoryPath,
        videoId,
        'images',
        'poster.jpg'
      );

      if (!fs.existsSync(posterPath)) {
        void reply.status(404).send('poster not found');
        return;
      }

      const fileStream = fs.createReadStream(posterPath);
      void reply.header('Content-Type', 'image/jpeg').send(fileStream);
    } catch (error) {
      this.logger.error('Get poster failed', error instanceof Error ? error : null);
      void reply.status(404).send('poster not found');
    }
  };

  /**
   * GET /external/videos/:videoId/adaptive/:format/:type/manifests/:manifestName
   *
   * Serve HLS/DASH manifest files
   */
  getAdaptiveManifest = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId, format, type, manifestName } = request.params as AdaptiveManifestParams;

      if (
        !isVideoIdValid(videoId, false) ||
        !isAdaptiveFormatValid(format) ||
        !isManifestTypeValid(type) ||
        !isManifestNameValid(manifestName)
      ) {
        void reply.status(404).send('video not found');
        return;
      }

      const config = getConfig();
      const manifestPath = path.join(
        config.paths.videosDirectoryPath,
        videoId,
        'adaptive',
        format,
        manifestName
      );

      if (!fs.existsSync(manifestPath)) {
        void reply.status(404).send('video not found');
        return;
      }

      const fileStream = fs.createReadStream(manifestPath);
      void reply.header('Content-Type', 'application/vnd.apple.mpegurl').send(fileStream);
    } catch (error) {
      this.logger.error('Get adaptive manifest failed', error instanceof Error ? error : null);
      void reply.status(404).send('video not found');
    }
  };

  /**
   * GET /external/videos/:videoId/adaptive/:format/:resolution/segments/:segmentName
   *
   * Serve HLS/DASH segment files with bandwidth tracking
   */
  getAdaptiveSegment = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId, format, resolution, segmentName } = request.params as AdaptiveSegmentParams;

      if (
        !isVideoIdValid(videoId, false) ||
        !isAdaptiveFormatValid(format) ||
        !isResolutionValid(resolution) ||
        !isSegmentNameValid(segmentName)
      ) {
        void reply.status(404).send('video not found');
        return;
      }

      const config = getConfig();
      const segmentPath = path.join(
        config.paths.videosDirectoryPath,
        videoId,
        'adaptive',
        format,
        resolution,
        segmentName
      );

      if (!fs.existsSync(segmentPath)) {
        void reply.status(404).send('video not found');
        return;
      }

      // Track bandwidth asynchronously
      this.trackSegmentBandwidth(segmentPath, videoId);

      const fileStream = fs.createReadStream(segmentPath);
      void reply.header('Content-Type', 'video/mp2t').send(fileStream);
    } catch (error) {
      this.logger.error('Get adaptive segment failed', error instanceof Error ? error : null);
      void reply.status(404).send('video not found');
    }
  };

  /**
   * GET /external/videos/:videoId/progressive/:format/:progressiveFilename
   *
   * Serve progressive video files with range request support
   */
  getProgressive = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId, format, progressiveFilename } = request.params as ProgressiveParams;

      if (
        !isVideoIdValid(videoId, false) ||
        !isProgressiveFormatValid(format) ||
        !isProgressiveFilenameValid(progressiveFilename)
      ) {
        void reply.status(404).send('video not found');
        return;
      }

      const config = getConfig();
      const filePath = path.join(
        config.paths.videosDirectoryPath,
        videoId,
        'progressive',
        format,
        progressiveFilename
      );

      if (!fs.existsSync(filePath)) {
        void reply.status(404).send('video not found');
        return;
      }

      const stat = fs.statSync(filePath);
      const fileSize = stat.size;
      const range = request.headers.range;

      if (typeof range === 'string' && range.length > 0) {
        // Handle range request
        const parts = range.replace(/bytes=/, '').split('-');
        const startPart = parts[0];
        const endPart = parts[1];
        const start =
          startPart !== undefined && startPart !== '' ? Number.parseInt(startPart, 10) : 0;
        const end =
          endPart !== undefined && endPart !== '' ? Number.parseInt(endPart, 10) : fileSize - 1;
        const chunkSize = end - start + 1;

        // Track bandwidth
        this.trackProgressiveBandwidth(chunkSize, videoId);

        const fileStream = fs.createReadStream(filePath, { start, end });

        void reply
          .status(206)
          .header('Content-Range', `bytes ${start}-${end}/${fileSize}`)
          .header('Accept-Ranges', 'bytes')
          .header('Content-Length', chunkSize)
          .header('Content-Type', `video/${format}`)
          .send(fileStream);
      } else {
        // Full file request
        const fileStream = fs.createReadStream(filePath);

        void reply
          .header('Content-Length', fileSize)
          .header('Content-Type', `video/${format}`)
          .send(fileStream);
      }
    } catch (error) {
      this.logger.error('Get progressive video failed', error instanceof Error ? error : null);
      void reply.status(404).send('video not found');
    }
  };

  /**
   * Track bandwidth for adaptive segments (debounced)
   */
  private trackSegmentBandwidth(segmentPath: string, videoId: string): void {
    fs.stat(segmentPath, (error, stats) => {
      if (error) {
        return;
      }

      this.segmentBandwidthCounter += stats.size;

      if (this.segmentBandwidthTimer) {
        clearTimeout(this.segmentBandwidthTimer);
      }

      this.segmentBandwidthTimer = setTimeout(() => {
        const bandwidth = this.segmentBandwidthCounter;
        this.segmentBandwidthCounter = 0;

        // Update bandwidth in database
        void this.videoRepository.updateBandwidth(videoId, bandwidth);
      }, 100);
    });
  }

  /**
   * Track bandwidth for progressive downloads (debounced)
   */
  private trackProgressiveBandwidth(chunkSize: number, videoId: string): void {
    this.progressiveBandwidthCounter += chunkSize;

    if (this.progressiveBandwidthTimer) {
      clearTimeout(this.progressiveBandwidthTimer);
    }

    this.progressiveBandwidthTimer = setTimeout(() => {
      const bandwidth = this.progressiveBandwidthCounter;
      this.progressiveBandwidthCounter = 0;

      // Update bandwidth in database
      void this.videoRepository.updateBandwidth(videoId, bandwidth);
    }, 100);
  }
}

/**
 * Node Controller
 *
 * Handles the main node page and related endpoints.
 */
import type { FastifyRequest, FastifyReply } from 'fastify';

import { BaseController } from './base.js';
import type { VideosRepository } from '../database/repositories/videos.js';
import type { CommentsRepository } from '../database/repositories/comments.js';
import type { ReportsVideosRepository } from '../database/repositories/reports-videos.js';
import type { ReportsCommentsRepository } from '../database/repositories/reports-comments.js';
import type { LinksRepository } from '../database/repositories/links.js';
import type { MonetizationRepository } from '../database/repositories/monetization.js';
import type { DrizzleVideo } from '../database/schema/index.js';
import { getConfig } from '../config/index.js';
import { isSearchTermValid, isSortTermValid, isTagTermValid } from '../utils/index.js';

/**
 * Fastify reply with view engine support
 */
interface FastifyReplyWithView extends FastifyReply {
  view?: (template: string, data: Record<string, unknown>) => FastifyReply;
}

/**
 * Query parameters for node page
 */
export interface NodeQuery {
  searchTerm?: string;
  sortTerm?: string;
  tagTerm?: string;
}

/**
 * Request body for content checked
 */
export interface ContentCheckedBody {
  contentType: 'comments' | 'videoReports' | 'commentReports';
}

/**
 * NodeController class
 *
 * Handles:
 * - Main node page rendering
 * - Video search
 * - New content counts
 * - Content check marking
 */
export class NodeController extends BaseController {
  constructor(
    private readonly videoRepository: VideosRepository,
    private readonly commentRepository: CommentsRepository,
    private readonly videoReportRepository: ReportsVideosRepository,
    private readonly commentReportRepository: ReportsCommentsRepository,
    private readonly linkRepository: LinksRepository,
    private readonly monetizationRepository: MonetizationRepository
  ) {
    super('NodeController');
  }

  /**
   * GET /node
   *
   * Render the main node page
   */
  getNodePage = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const queryParams = request.query as NodeQuery;

      // Validate and sanitize query parameters
      const searchTerm = isSearchTermValid(queryParams.searchTerm ?? '')
        ? (queryParams.searchTerm ?? '')
        : '';
      const sortTerm = isSortTermValid(queryParams.sortTerm ?? '')
        ? (queryParams.sortTerm ?? 'latest')
        : 'latest';
      const tagTerm = isTagTermValid(queryParams.tagTerm ?? '', true)
        ? (queryParams.tagTerm ?? '')
        : '';

      const config = getConfig();
      const nodeSettings = config.nodeSettings;

      // Get node information
      const videoCount = await this.videoRepository.count({ isPublished: true });
      const informationData = {
        isError: false,
        information: {
          nodeVideoCount: videoCount,
          nodeId: String(nodeSettings.nodeId ?? ''),
          nodeName: String(nodeSettings.nodeName ?? ''),
          nodeAbout: String(nodeSettings.nodeAbout ?? ''),
          publicNodeProtocol: String(nodeSettings.publicNodeProtocol ?? ''),
          publicNodeAddress: String(nodeSettings.publicNodeAddress ?? ''),
          publicNodePort: String(nodeSettings.publicNodePort ?? ''),
          cloudflareTurnstileSiteKey: String(nodeSettings.cloudflareTurnstileSiteKey ?? ''),
        },
      };

      // Get links
      const links = await this.linkRepository.findAll();
      const linksData = { isError: false, links };

      // Get crypto wallet addresses
      const walletAddresses = await this.monetizationRepository.findAll();
      const cryptoWalletAddressesData = { isError: false, cryptoWalletAddresses: walletAddresses };

      // Get all unique tags
      const allVideos = await this.videoRepository.findAll({
        isPublished: true,
      });

      const tagsSet = new Set<string>();
      for (const video of allVideos) {
        const videoTags = video.tags?.split(',') ?? [];
        for (const tag of videoTags) {
          if (tag.trim()) {
            tagsSet.add(tag.trim());
          }
        }
      }
      const tagsData = { isError: false, tags: Array.from(tagsSet) };

      // Get search results
      const searchResultsData = await this.performSearch(searchTerm, sortTerm, tagTerm);

      const externalVideosBaseUrl = config.getExternalVideosBaseUrl();
      const externalResourcesBaseUrl = config.getExternalResourcesBaseUrl();

      // Render the node page
      const replyWithView = reply as FastifyReplyWithView;
      if (replyWithView.view) {
        void replyWithView.view('node', {
          informationData,
          linksData,
          cryptoWalletAddressesData,
          tagsData,
          searchResultsData,
          externalVideosBaseUrl,
          externalResourcesBaseUrl,
        });
      } else {
        // Fallback to JSON response if view engine not available
        void reply.send({
          informationData,
          linksData,
          cryptoWalletAddressesData,
          tagsData,
          searchResultsData,
          externalVideosBaseUrl,
          externalResourcesBaseUrl,
        });
      }
    } catch (error) {
      this.logger.error('Node page rendering failed', error instanceof Error ? error : null);
      void reply.status(500).send('node page rendering error');
    }
  };

  /**
   * GET /node/search
   *
   * Search videos
   */
  search = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const queryParams = request.query as NodeQuery;

      // Validate parameters
      const searchTerm = isSearchTermValid(queryParams.searchTerm ?? '')
        ? (queryParams.searchTerm ?? '')
        : '';
      const sortTerm = isSortTermValid(queryParams.sortTerm ?? '')
        ? (queryParams.sortTerm ?? 'latest')
        : 'latest';
      const tagTerm = isTagTermValid(queryParams.tagTerm ?? '', true)
        ? (queryParams.tagTerm ?? '')
        : '';

      const data = await this.performSearch(searchTerm, sortTerm, tagTerm);
      this.sendSuccess(reply, { searchResults: data.searchResults });
    } catch (error) {
      this.logger.error('Search failed', error instanceof Error ? error : null);
      this.sendError(reply, 'error communicating with the MoarTube node');
    }
  };

  /**
   * GET /node/newContentCounts
   *
   * Get counts of new content since last check
   */
  getNewContentCounts = async (_request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const config = getConfig();
      const lastCheckedContentTracker = config.lastCheckedContentTracker;

      const lastCheckedCommentsTimestamp = lastCheckedContentTracker.lastCheckedCommentsTimestamp;
      const lastCheckedVideoReportsTimestamp =
        lastCheckedContentTracker.lastCheckedVideoReportsTimestamp;
      const lastCheckedCommentReportsTimestamp =
        lastCheckedContentTracker.lastCheckedCommentReportsTimestamp;

      // Count new content since last check
      const newCommentsCount = await this.commentRepository.countNewerThan(
        lastCheckedCommentsTimestamp
      );
      const newVideoReportsCount = await this.videoReportRepository.countNewerThan(
        lastCheckedVideoReportsTimestamp
      );
      const newCommentReportsCount = await this.commentReportRepository.countNewerThan(
        lastCheckedCommentReportsTimestamp
      );

      this.sendSuccess(reply, {
        newContentCounts: {
          newCommentsCount,
          newVideoReportsCount,
          newCommentReportsCount,
        },
      });
    } catch (error) {
      this.logger.error('Get new content counts failed', error instanceof Error ? error : null);
      this.sendError(reply, 'error communicating with the MoarTube node');
    }
  };

  /**
   * POST /node/contentChecked
   *
   * Mark content type as checked
   */
  contentChecked = (request: FastifyRequest, reply: FastifyReply): void => {
    try {
      const { contentType } = request.body as ContentCheckedBody;
      const config = getConfig();

      const timestamp = Date.now();

      if (contentType === 'comments') {
        config.updateLastCheckedContentTracker({ lastCheckedCommentsTimestamp: timestamp });
      } else if (contentType === 'videoReports') {
        config.updateLastCheckedContentTracker({ lastCheckedVideoReportsTimestamp: timestamp });
      } else if (contentType === 'commentReports') {
        config.updateLastCheckedContentTracker({ lastCheckedCommentReportsTimestamp: timestamp });
      }

      this.sendOk(reply);
    } catch (error) {
      this.logger.error('Content checked failed', error instanceof Error ? error : null);
      this.sendError(reply, 'error communicating with the MoarTube node');
    }
  };

  /**
   * Perform video search with sorting and tag filtering
   */
  private async performSearch(
    searchTerm: string,
    sortTerm: string,
    tagTerm: string
  ): Promise<{ isError: false; searchResults: DrizzleVideo[] }> {
    const videos = await this.fetchAndMergeVideos(searchTerm);
    const sortedVideos = this.sortVideos(videos, sortTerm);
    const searchResults = this.filterByTag(sortedVideos, tagTerm);

    return { isError: false, searchResults };
  }

  /**
   * Fetch published and live videos, merge and deduplicate
   */
  private async fetchAndMergeVideos(searchTerm: string): Promise<DrizzleVideo[]> {
    const queryOptions: { isPublished: boolean; search?: string } = {
      isPublished: true,
    };

    if (searchTerm.length > 0) {
      queryOptions.search = searchTerm;
    }

    const videos = await this.videoRepository.findAll(queryOptions);
    const liveVideos = await this.videoRepository.findStreaming();

    const videoMap = new Map<string, DrizzleVideo>();
    for (const video of videos) {
      videoMap.set(video.videoId, video);
    }
    for (const video of liveVideos) {
      if (!videoMap.has(video.videoId)) {
        videoMap.set(video.videoId, video);
      }
    }

    return Array.from(videoMap.values());
  }

  /**
   * Sort videos by the given sort term
   */
  private sortVideos(videos: DrizzleVideo[], sortTerm: string): DrizzleVideo[] {
    const sorted = [...videos];

    if (sortTerm === 'latest') {
      sorted.sort((a, b) => b.creationTimestamp - a.creationTimestamp);
    } else if (sortTerm === 'popular') {
      sorted.sort((a, b) => b.views - a.views);
    } else if (sortTerm === 'oldest') {
      sorted.sort((a, b) => a.creationTimestamp - b.creationTimestamp);
    }

    return sorted;
  }

  /**
   * Filter videos by tag with optional tag limit
   */
  private filterByTag(videos: DrizzleVideo[], tagTerm: string): DrizzleVideo[] {
    if (tagTerm.length > 0) {
      return this.filterBySpecificTag(videos, tagTerm);
    }
    return this.filterWithTagLimit(videos);
  }

  /**
   * Filter videos that have a specific tag
   */
  private filterBySpecificTag(videos: DrizzleVideo[], tagTerm: string): DrizzleVideo[] {
    const results: DrizzleVideo[] = [];

    for (const video of videos) {
      const tagsArray = video.tags?.split(',').map((t: string) => t.trim()) ?? [];
      if (tagsArray.includes(tagTerm) && !results.includes(video)) {
        results.push(video);
      }
    }

    return results;
  }

  /**
   * Filter videos with a limit per tag
   */
  private filterWithTagLimit(videos: DrizzleVideo[]): DrizzleVideo[] {
    const tagLimit = 4;
    const tagLimitCounter: Record<string, number> = {};
    const results: DrizzleVideo[] = [];

    for (const video of videos) {
      if (this.shouldAddVideoByTagLimit(video, tagLimitCounter, tagLimit)) {
        results.push(video);
      }
    }

    return results;
  }

  /**
   * Check if video should be added based on tag limit
   */
  private shouldAddVideoByTagLimit(
    video: DrizzleVideo,
    tagLimitCounter: Record<string, number>,
    tagLimit: number
  ): boolean {
    const tagsArray = video.tags?.split(',') ?? [];

    for (const tag of tagsArray) {
      const trimmedTag = tag.trim();
      if (trimmedTag === '') {
        continue;
      }

      if (!(trimmedTag in tagLimitCounter)) {
        tagLimitCounter[trimmedTag] = 0;
      }

      const currentCount = tagLimitCounter[trimmedTag] ?? 0;
      if (currentCount < tagLimit) {
        tagLimitCounter[trimmedTag] = currentCount + 1;
        return true;
      }
    }

    return false;
  }
}

/**
 * Status Controller
 *
 * Handles status and health check endpoints.
 */
import type { FastifyRequest, FastifyReply } from 'fastify';
import { BaseController } from './base.js';
import { getConfig } from '../config/index.js';
import type { Container } from '../core/container.js';

/**
 * Status information response
 */
interface StatusInformation {
  nodeVideoCount: number;
  nodeId: string;
  nodeName: string;
  nodeAbout: string;
  publicNodeProtocol: string;
  publicNodeAddress: string;
  publicNodePort: string;
  cloudflareTurnstileSiteKey: string;
}

interface HealthCheck {
  status: 'ok' | 'error';
  message?: string;
}

/**
 * StatusController class
 *
 * Handles:
 * - Node information endpoint
 * - Heartbeat endpoint
 * - Health checks
 */
export class StatusController extends BaseController {
  private readonly container: Container;

  constructor(container: Container) {
    super('StatusController');
    this.container = container;
  }

  /**
   * GET /status/information
   *
   * Returns node information including video count and public settings
   */
  information = async (_request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const config = getConfig();
    const nodeSettings = config.nodeSettings;

    // Get video count from repository
    const videoRepository = this.container.resolve('videoRepository');
    const videoCount = await videoRepository.count({
      isPublished: true,
    });

    const information: StatusInformation = {
      nodeVideoCount: videoCount,
      nodeId: String(nodeSettings.nodeId ?? ''),
      nodeName: String(nodeSettings.nodeName ?? ''),
      nodeAbout: String(nodeSettings.nodeAbout ?? ''),
      publicNodeProtocol: String(nodeSettings.publicNodeProtocol ?? ''),
      publicNodeAddress: String(nodeSettings.publicNodeAddress ?? ''),
      publicNodePort: String(nodeSettings.publicNodePort ?? ''),
      cloudflareTurnstileSiteKey: String(nodeSettings.cloudflareTurnstileSiteKey ?? ''),
    };

    this.sendSuccess(reply, { information });
  };

  /**
   * GET /status/heartbeat
   *
   * Returns current timestamp for health checks
   */
  heartbeat = (_request: FastifyRequest, reply: FastifyReply): void => {
    this.sendSuccess(reply, { timestamp: Date.now() });
  };

  /**
   * GET /health
   *
   * Basic liveness check
   */
  health = (_request: FastifyRequest, reply: FastifyReply): void => {
    void reply.send({ status: 'ok', timestamp: Date.now() });
  };

  /**
   * GET /health/ready
   *
   * Detailed readiness check including database connectivity
   */
  healthReady = async (_request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    let databaseCheck: HealthCheck = { status: 'ok' };
    let configurationCheck: HealthCheck = { status: 'ok' };

    // Check database connectivity
    try {
      const videoRepository = this.container.resolve('videoRepository');
      await videoRepository.count({});
    } catch (error) {
      databaseCheck = {
        status: 'error',
        message: (error as Error).message,
      };
    }

    // Check configuration
    try {
      const config = getConfig();
      const nodeId = config.nodeSettings.nodeId;
      if (nodeId === undefined || nodeId === '') {
        configurationCheck = {
          status: 'error',
          message: 'Node not configured',
        };
      }
    } catch (error) {
      configurationCheck = {
        status: 'error',
        message: (error as Error).message,
      };
    }

    const isHealthy = databaseCheck.status === 'ok' && configurationCheck.status === 'ok';
    const httpStatus = isHealthy ? 200 : 503;

    void reply.status(httpStatus).send({
      status: isHealthy ? 'ok' : 'degraded',
      timestamp: Date.now(),
      checks: {
        database: databaseCheck,
        configuration: configurationCheck,
      },
    });
  };
}

/**
 * Streams Controller
 *
 * Handles live streaming endpoints.
 */
import fs from 'node:fs';
import path from 'node:path';
import type { FastifyRequest, FastifyReply } from 'fastify';

import { BaseController } from './base.js';
import type { VideosRepository } from '../database/repositories/videos.js';
import type { LiveChatMessageRepository } from '../database/repositories/live-chat-messages.js';
import type { StreamService } from '../services/stream.js';
import { getConfig } from '../config/index.js';
import {
  isTitleValid,
  isDescriptionValid,
  isTagsValid,
  isPortValid,
  isVideoIdValid,
  isAdaptiveFormatValid,
  isResolutionValid,
  isSegmentNameValid,
  isBooleanValid,
  isNetworkAddressValid,
  isChatHistoryLimitValid,
} from '../utils/index.js';

/**
 * Request body for starting a stream
 */
export interface StartStreamBody {
  title: string;
  description: string;
  tags: string;
  rtmpPort: string;
  uuid: string;
  isRecordingStreamRemotely: boolean;
  isRecordingStreamLocally: boolean;
  networkAddress: string;
  resolution: string;
  videoId?: string;
}

/**
 * Request params with videoId
 */
export interface VideoIdParams {
  videoId: string;
}

/**
 * Request params for segment removal
 */
export interface SegmentRemoveParams {
  videoId: string;
  format: string;
  resolution: string;
}

/**
 * Request body for segment removal
 */
export interface SegmentRemoveBody {
  segmentName: string;
}

/**
 * Request body for chat settings
 */
export interface ChatSettingsBody {
  isChatHistoryEnabled: boolean;
  chatHistoryLimit: number;
}

/**
 * StreamsController class
 *
 * Handles:
 * - Starting streams
 * - Stopping streams
 * - Stream segment management
 * - Stream bandwidth
 * - Chat settings and history
 */
export class StreamsController extends BaseController {
  constructor(
    private readonly videoRepository: VideosRepository,
    private readonly liveChatMessageRepository: LiveChatMessageRepository,
    private readonly streamService: StreamService
  ) {
    super('StreamsController');
  }

  /**
   * POST /streams/start
   *
   * Start a new stream or resume an existing one
   */
  startStream = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const {
        title,
        description,
        tags,
        rtmpPort,
        uuid,
        isRecordingStreamRemotely,
        isRecordingStreamLocally,
        networkAddress,
        resolution,
        videoId = '',
      } = request.body as StartStreamBody;

      // Validate all parameters
      if (!isTitleValid(title)) {
        this.sendError(reply, 'title is not valid');
        return;
      }
      if (!isDescriptionValid(description)) {
        this.sendError(reply, 'description is not valid');
        return;
      }
      if (!isTagsValid(tags)) {
        this.sendError(reply, 'tags are not valid');
        return;
      }
      if (!isPortValid(rtmpPort)) {
        this.sendError(reply, 'rtmp port not valid');
        return;
      }
      if (uuid !== 'moartube') {
        this.sendError(reply, 'uuid not valid');
        return;
      }
      if (!isBooleanValid(isRecordingStreamRemotely)) {
        this.sendError(reply, 'isRecordingStreamRemotely not valid');
        return;
      }
      if (!isBooleanValid(isRecordingStreamLocally)) {
        this.sendError(reply, 'isRecordingStreamLocally not valid');
        return;
      }
      if (!isNetworkAddressValid(networkAddress)) {
        this.sendError(reply, 'networkAddress not valid');
        return;
      }
      if (!isResolutionValid(resolution)) {
        this.sendError(reply, 'resolution not valid');
        return;
      }
      if (!isVideoIdValid(videoId, true)) {
        this.sendError(reply, 'videoId not valid');
        return;
      }

      const options: {
        title: string;
        description: string;
        tags: string;
        rtmpPort: number;
        isRecordingStreamRemotely: boolean;
        isRecordingStreamLocally: boolean;
        networkAddress: string;
        resolution: string;
        existingVideoId?: string;
      } = {
        title,
        description,
        tags,
        rtmpPort: Number.parseInt(rtmpPort, 10),
        isRecordingStreamRemotely,
        isRecordingStreamLocally,
        networkAddress,
        resolution,
      };

      if (videoId.length > 0) {
        options.existingVideoId = videoId;
      }

      const result = await this.streamService.startNewStream(options);

      this.sendSuccess(reply, { videoId: result.videoId });
    } catch (error) {
      this.logger.error('Start stream failed', error instanceof Error ? error : null);
      this.sendError(reply, 'error communicating with the MoarTube node');
    }
  };

  /**
   * POST /streams/:videoId/stop
   *
   * Stop a stream
   */
  stopStream = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId } = request.params as VideoIdParams;

      if (!isVideoIdValid(videoId, false)) {
        this.sendError(reply, 'video id is not valid');
        return;
      }

      await this.streamService.stopStream(videoId);

      this.sendOk(reply);
    } catch (error) {
      this.logger.error('Stop stream failed', error instanceof Error ? error : null);
      this.sendError(reply, 'error communicating with the MoarTube node');
    }
  };

  /**
   * POST /streams/:videoId/adaptive/:format/:resolution/segments/remove
   *
   * Remove a segment file
   */
  removeSegment = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId, format, resolution } = request.params as SegmentRemoveParams;
      const { segmentName } = request.body as SegmentRemoveBody;

      if (
        !isVideoIdValid(videoId, false) ||
        !isAdaptiveFormatValid(format) ||
        !isResolutionValid(resolution) ||
        !isSegmentNameValid(segmentName)
      ) {
        this.sendError(reply, 'invalid parameters');
        return;
      }

      // Delete the segment file directly
      const config = getConfig();
      const segmentPath = path.join(
        config.paths.videosDirectoryPath,
        videoId,
        'adaptive',
        format,
        resolution,
        segmentName
      );

      try {
        if (fs.existsSync(segmentPath)) {
          fs.unlinkSync(segmentPath);
        }
      } catch {
        // Ignore file deletion errors
      }

      this.sendOk(reply);
    } catch (error) {
      this.logger.error('Remove segment failed', error instanceof Error ? error : null);
      this.sendError(reply, 'error communicating with the MoarTube node');
    }
  };

  /**
   * GET /streams/:videoId/bandwidth
   *
   * Get stream bandwidth
   */
  getBandwidth = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId } = request.params as VideoIdParams;

      if (!isVideoIdValid(videoId, false)) {
        this.sendError(reply, 'invalid parameters');
        return;
      }

      const video = await this.videoRepository.findById(videoId);

      if (video === null) {
        this.sendError(reply, 'that video does not exist');
        return;
      }

      this.sendSuccess(reply, { bandwidth: video.bandwidth });
    } catch (error) {
      this.logger.error('Get bandwidth failed', error instanceof Error ? error : null);
      this.sendError(reply, 'error communicating with the MoarTube node');
    }
  };

  /**
   * POST /streams/:videoId/chat/settings
   *
   * Update chat settings for a stream
   */
  updateChatSettings = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId } = request.params as VideoIdParams;
      const { isChatHistoryEnabled, chatHistoryLimit } = request.body as ChatSettingsBody;

      if (
        !isVideoIdValid(videoId, false) ||
        !isBooleanValid(isChatHistoryEnabled) ||
        !isChatHistoryLimitValid(chatHistoryLimit)
      ) {
        this.sendError(reply, 'invalid parameters');
        return;
      }

      const video = await this.videoRepository.findById(videoId);

      if (video === null) {
        this.sendError(reply, 'that video does not exist');
        return;
      }

      // Update meta with chat settings
      let meta: Record<string, unknown> = {};
      if (video.meta !== undefined && video.meta !== null && video.meta !== '') {
        try {
          meta = JSON.parse(String(video.meta)) as Record<string, unknown>;
        } catch {
          // Invalid JSON
        }
      }

      const chatSettings = (meta['chatSettings'] as Record<string, unknown>) ?? {};
      chatSettings['isChatHistoryEnabled'] = isChatHistoryEnabled;
      chatSettings['chatHistoryLimit'] = chatHistoryLimit;
      meta['chatSettings'] = chatSettings;

      await this.videoRepository.update(videoId, { meta: JSON.stringify(meta) });

      // Clean up chat history if disabled or limited
      if (!isChatHistoryEnabled) {
        await this.liveChatMessageRepository.deleteByVideoId(videoId);
      } else if (chatHistoryLimit > 0) {
        await this.liveChatMessageRepository.pruneOldMessages(videoId, chatHistoryLimit);
      }

      this.sendOk(reply);
    } catch (error) {
      this.logger.error('Update chat settings failed', error instanceof Error ? error : null);
      this.sendError(reply, 'error communicating with the MoarTube node');
    }
  };

  /**
   * GET /streams/:videoId/chat/history
   *
   * Get chat history for a stream
   */
  getChatHistory = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId } = request.params as VideoIdParams;

      if (!isVideoIdValid(videoId, false)) {
        this.sendError(reply, 'invalid parameters');
        return;
      }

      const chatHistory = await this.liveChatMessageRepository.findByVideoId(videoId);

      this.sendSuccess(reply, { chatHistory });
    } catch (error) {
      this.logger.error('Get chat history failed', error instanceof Error ? error : null);
      this.sendError(reply, 'error communicating with the MoarTube node');
    }
  };
}

/**
 * Videos Controller
 *
 * Handles HTTP requests for video-related operations.
 * Migrated from Express to Fastify with proper TypeScript types.
 */

import * as fs from 'node:fs';
import * as path from 'node:path';
import type { FastifyRequest, FastifyReply } from 'fastify';
import { BaseController } from './base.js';
import type {
  IVideoService,
  ICommentService,
  ICloudflareService,
  IReportService,
  UpdateVideoInput,
  ReportType,
} from '../services/interfaces.js';
import type { IVideoUploadService } from '../services/index.js';
import { NotFoundError, BadRequestError, ForbiddenError } from '../errors/index.js';
import { resolve } from '../core/container.js';
import { getConfig } from '../config/index.js';

/**
 * Request body/query/params type definitions
 */
interface VideoIdParams {
  videoId: string;
}

interface VideoSearchQuery {
  searchTerm?: string;
  sortTerm?: 'latest' | 'popular' | 'oldest';
  tagTerm?: string;
  tagLimit?: number;
  timestamp?: number;
}

interface VideoImportBody {
  title: string;
  description: string;
  tags: string;
}

interface VideoUpdateBody {
  title?: string;
  description?: string;
  tags?: string;
}

interface VideoCommentsQuery {
  timestamp?: number;
  type?: string;
}

interface CommentBody {
  commentPlainText: string;
  timestamp?: number;
  cloudflareTurnstileToken?: string;
}

interface LikeDislikeBody {
  cloudflareTurnstileToken?: string;
}

interface ReportBody {
  email: string;
  reportType: ReportType;
  message: string;
  cloudflareTurnstileToken?: string;
}

interface FormatResolutionBody {
  format: 'm3u8' | 'mp4' | 'webm' | 'ogv';
  resolution: '2160p' | '1440p' | '1080p' | '720p' | '480p' | '360p' | '240p';
}

interface SourceFileExtensionBody {
  sourceFileExtension: string;
}

interface UploadQueryParams {
  format: string;
  resolution: string;
}

type ImageType = 'thumbnail' | 'preview' | 'poster';

/**
 * VideosController class
 *
 * Handles all video-related HTTP endpoints including:
 * - Video CRUD operations
 * - Video search and listing
 * - Video interactions (likes, dislikes, comments)
 * - Video publishing workflow
 * - Video import/export workflow
 */
export class VideosController extends BaseController {
  constructor() {
    super('VideosController');
  }

  /**
   * Get video service from DI container
   */
  private getVideoService(): IVideoService {
    return resolve('videoService');
  }

  /**
   * Get comment service from DI container
   */
  private getCommentService(): ICommentService {
    return resolve('commentService');
  }

  /**
   * Get video upload service from DI container
   */
  private getVideoUploadService(): IVideoUploadService {
    return resolve('videoUploadService');
  }

  // Reserved for future upload tracking - uncomment when needed
  // private getUploadTrackerService(): IUploadTrackerService {
  //   return resolve('uploadTrackerService');
  // }

  /**
   * Get Cloudflare service from DI container
   */
  private getCloudflareService(): ICloudflareService {
    return resolve('cloudflareService');
  }

  /**
   * Get report service from DI container
   */
  private getReportService(): IReportService {
    return resolve('reportService');
  }

  /**
   * Validate Cloudflare Turnstile token if enabled
   */
  private async validateTurnstileIfEnabled(request: FastifyRequest, token?: string): Promise<void> {
    const config = getConfig();
    const nodeSettings = config.nodeSettings;

    if (!nodeSettings.isCloudflareTurnstileEnabled) {
      return; // Turnstile not enabled, validation passes
    }

    if (!token || token.length === 0) {
      throw new ForbiddenError(
        'Human verification is enabled on this MoarTube Node, please refresh your browser'
      );
    }

    const cloudflareService = this.getCloudflareService();
    const clientIp = request.ip || '';

    const isValid = await cloudflareService.validateTurnstileToken(token, clientIp);
    if (!isValid) {
      throw new ForbiddenError('Human verification failed');
    }
  }

  /**
   * Import a new video
   * POST /videos/import
   */
  importVideo = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const videoService = this.getVideoService();
    const { title, description, tags } = request.body as VideoImportBody;

    const result = await videoService.createVideo({ title, description, tags });

    this.sendSuccess(reply, result, 'Video imported successfully');
  };

  /**
   * Mark video as imported (import complete)
   * POST /videos/imported
   *
   * Takes videoId from request body (legacy route)
   */
  videoImportedFromBody = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const videoService = this.getVideoService();
    const { videoId } = request.body as { videoId: string };

    if (!videoId) {
      throw new BadRequestError('videoId is required');
    }

    await videoService.setImported(videoId);

    this.sendSuccess(reply, {});
  };

  /**
   * Start publishing process
   * POST /videos/publishing
   *
   * Takes videoId from request body (legacy route)
   */
  startPublishingFromBody = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const videoService = this.getVideoService();
    const { videoId } = request.body as { videoId: string };

    if (!videoId) {
      throw new BadRequestError('videoId is required');
    }

    await videoService.setPublishing(videoId, true);

    this.sendSuccess(reply, {});
  };

  /**
   * Mark video as published (publishing complete)
   * POST /videos/published
   *
   * Takes videoId from request body (legacy route)
   */
  videoPublishedFromBody = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const videoService = this.getVideoService();
    const { videoId } = request.body as { videoId: string };

    if (!videoId) {
      throw new BadRequestError('videoId is required');
    }

    await videoService.setPublishing(videoId, false);
    await videoService.publishVideo(videoId);

    this.sendSuccess(reply, {});
  };

  /**
   * Mark video as imported (import complete)
   * POST /videos/:videoId/imported
   */
  videoImported = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const videoService = this.getVideoService();
    const { videoId } = request.params as VideoIdParams;

    await videoService.setImported(videoId);

    this.sendSuccess(reply, { videoId }, 'Video import completed');
  };

  /**
   * Stop video import process
   * POST /videos/:videoId/importing/stop
   */
  stopImporting = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const videoService = this.getVideoService();
    const { videoId } = request.params as VideoIdParams;

    await videoService.setImporting(videoId, false);

    this.sendSuccess(reply, { videoId }, 'Video import stopped');
  };

  /**
   * Mark video as publishing (start publishing)
   * POST /videos/:videoId/publishing
   */
  startPublishing = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const videoService = this.getVideoService();
    const { videoId } = request.params as VideoIdParams;

    await videoService.setPublishing(videoId, true);

    this.sendSuccess(reply, { videoId }, 'Video publishing started');
  };

  /**
   * Mark video as published (publishing complete)
   * POST /videos/:videoId/published
   */
  videoPublished = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const videoService = this.getVideoService();
    const { videoId } = request.params as VideoIdParams;

    await videoService.setPublishing(videoId, false);
    await videoService.publishVideo(videoId);

    this.sendSuccess(reply, { videoId }, 'Video publishing completed');
  };

  /**
   * Mark specific format/resolution as published
   * POST /videos/:videoId/format-resolution/published
   */
  formatResolutionPublished = async (
    request: FastifyRequest,
    reply: FastifyReply
  ): Promise<void> => {
    const videoService = this.getVideoService();
    const { videoId } = request.params as VideoIdParams;
    const { format, resolution } = request.body as FormatResolutionBody;

    if (!format || !resolution) {
      throw new BadRequestError('Format and resolution are required');
    }

    await videoService.markFormatResolutionPublished(videoId, format, resolution);

    this.sendSuccess(reply, { videoId, format, resolution }, 'Format/resolution published');
  };

  /**
   * Stop video publishing process
   * POST /videos/:videoId/publishing/stop
   */
  stopPublishing = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const videoService = this.getVideoService();
    const { videoId } = request.params as VideoIdParams;

    await videoService.setPublishing(videoId, false);

    this.sendSuccess(reply, { videoId }, 'Video publishing stopped');
  };

  /**
   * Notify video upload complete
   * POST /videos/:videoId/upload
   */
  videoUploaded = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const videoService = this.getVideoService();
    const { videoId } = request.params as VideoIdParams;
    const { format, resolution } = request.body as FormatResolutionBody;

    if (!format || !resolution) {
      throw new BadRequestError('Format and resolution are required');
    }

    await videoService.notifyUploadComplete(videoId, format, resolution);

    this.sendSuccess(reply, { videoId }, 'Video upload notification processed');
  };

  /**
   * Notify video stream complete
   * POST /videos/:videoId/stream
   */
  videoStreamed = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const videoService = this.getVideoService();
    const { videoId } = request.params as VideoIdParams;
    const { format, resolution } = request.body as FormatResolutionBody;

    if (!format || !resolution) {
      throw new BadRequestError('Format and resolution are required');
    }

    await videoService.notifyStreamComplete(videoId, format, resolution);

    this.sendSuccess(reply, { videoId }, 'Video stream notification processed');
  };

  /**
   * Mark video as error state
   * POST /videos/:videoId/error
   */
  videoError = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const videoService = this.getVideoService();
    const { videoId } = request.params as VideoIdParams;

    await videoService.setError(videoId, true);

    this.sendSuccess(reply, { videoId }, 'Video marked as error');
  };

  /**
   * Mark video as error state (videoId from body)
   * POST /videos/error
   *
   * This is the legacy route that takes videoId from request body
   */
  setErrorFromBody = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const videoService = this.getVideoService();
    const { videoId } = request.body as { videoId: string };

    if (!videoId) {
      throw new BadRequestError('videoId is required');
    }

    await videoService.setError(videoId, true);

    this.sendSuccess(reply, {});
  };

  /**
   * Set video source file extension
   * POST /videos/:videoId/source-file-extension
   */
  setSourceFileExtension = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const videoService = this.getVideoService();
    const { videoId } = request.params as VideoIdParams;
    const { sourceFileExtension } = request.body as SourceFileExtensionBody;

    if (!sourceFileExtension) {
      throw new BadRequestError('Source file extension is required');
    }

    await videoService.setSourceFileExtension(videoId, sourceFileExtension);

    this.sendSuccess(reply, { videoId, sourceFileExtension }, 'Source file extension set');
  };

  /**
   * Get video source file extension
   * GET /videos/:videoId/source-file-extension
   */
  getSourceFileExtension = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const videoService = this.getVideoService();
    const { videoId } = request.params as VideoIdParams;

    const sourceFileExtension = await videoService.getSourceFileExtension(videoId);

    if (sourceFileExtension === null) {
      throw new NotFoundError(`Video not found: ${videoId}`);
    }

    this.sendSuccess(reply, { sourceFileExtension });
  };

  /**
