/**
 * Write Queue for cluster IPC-based database operations
 *
 * In a clustered Node.js application, SQLite requires that all write operations
 * are performed by the master process to avoid database locking issues.
 * This queue handles sending write operations from worker processes to the master.
 */
import { randomUUID } from 'crypto';

/**
 * Pending job interface for tracking submitted write operations
 */
interface PendingJob<T = void> {
  resolve: (value: T) => void;
  reject: (error: Error) => void;
  timestamp: number;
}

/**
 * Database write job message sent via IPC
 */
export interface DatabaseWriteJobMessage {
  cmd: 'database_write_job';
  query: string;
  parameters: unknown[];
  databaseWriteJobId: string;
}

/**
 * Database write job result message received via IPC
 */
export interface DatabaseWriteJobResultMessage {
  cmd: 'database_write_job_result';
  databaseWriteJobId: string;
  error?: string;
  result?: unknown;
}

/**
 * WriteQueue class for managing database write operations in clustered mode
 *
 * Workers submit write operations to this queue, which sends them to the master
 * process via IPC. The master executes the query and sends back the result.
 */
export class WriteQueue {
  private pendingJobs = new Map<string, PendingJob<unknown>>();
  private readonly jobTimeout: number;

  /**
   * Creates a new WriteQueue instance
   *
   * @param jobTimeout - Maximum time in milliseconds to wait for a job to complete (default: 30000)
   */
  constructor(jobTimeout = 30000) {
    this.jobTimeout = jobTimeout;
    this.setupMessageHandler();
    this.startTimeoutChecker();
  }

  /**
   * Submits a database write operation to be executed by the master process
   *
   * @param query - The SQL query string to execute
   * @param parameters - Query parameters
   * @returns Promise that resolves when the write operation completes
   * @throws Error if the operation fails or times out
   */
  submit(query: string, parameters: unknown[] = []): Promise<void> {
    return new Promise((resolve, reject) => {
      const jobId = randomUUID();

      this.pendingJobs.set(jobId, {
        resolve: resolve as (value: unknown) => void,
        reject,
        timestamp: Date.now(),
      });

      const message: DatabaseWriteJobMessage = {
        cmd: 'database_write_job',
        query,
        parameters,
        databaseWriteJobId: jobId,
      };

      // Send to master process
      if (typeof process.send === 'function') {
        process.send(message);
      } else {
        // Not in cluster mode - execute directly would require different handling
        this.pendingJobs.delete(jobId);
        reject(new Error('WriteQueue: Not running in cluster worker mode'));
      }
    });
  }

  /**
   * Submits a database write operation that returns a result
   *
   * @param query - The SQL query string to execute
   * @param parameters - Query parameters
   * @returns Promise that resolves with the query result
   * @throws Error if the operation fails or times out
   */
  submitWithResult<T>(query: string, parameters: unknown[] = []): Promise<T> {
    return new Promise((resolve, reject) => {
      const jobId = randomUUID();

      this.pendingJobs.set(jobId, {
        resolve: resolve as (value: unknown) => void,
        reject,
        timestamp: Date.now(),
      });

      const message: DatabaseWriteJobMessage = {
        cmd: 'database_write_job',
        query,
        parameters,
        databaseWriteJobId: jobId,
      };

      if (typeof process.send === 'function') {
        process.send(message);
      } else {
        this.pendingJobs.delete(jobId);
        reject(new Error('WriteQueue: Not running in cluster worker mode'));
      }
    });
  }

  /**
   * Completes a pending job with optional result or error
   *
   * Called by the message handler when a result is received from the master.
   *
   * @param jobId - The unique job identifier
   * @param error - Optional error if the operation failed
   * @param result - Optional result data from the operation
   */
  complete(jobId: string, error?: Error, result?: unknown): void {
    const job = this.pendingJobs.get(jobId);

    if (job) {
      this.pendingJobs.delete(jobId);

      if (error) {
        job.reject(error);
      } else {
        job.resolve(result);
      }
    }
  }

  /**
   * Gets the number of pending jobs
   *
   * @returns Number of jobs awaiting completion
   */
  getPendingCount(): number {
    return this.pendingJobs.size;
  }

  /**
   * Clears all pending jobs with an error
   *
   * Used during shutdown or when the connection to master is lost.
   *
   * @param error - Error to reject all pending jobs with
   */
  clearAllPending(error: Error): void {
    for (const [jobId, job] of this.pendingJobs) {
      job.reject(error);
      this.pendingJobs.delete(jobId);
    }
  }

  /**
   * Sets up the IPC message handler for receiving results from master
   */
  private setupMessageHandler(): void {
    process.on('message', (message: unknown) => {
      if (
        typeof message === 'object' &&
        message !== null &&
        'cmd' in message &&
        (message as { cmd: string }).cmd === 'database_write_job_result'
      ) {
        const resultMessage = message as DatabaseWriteJobResultMessage;
        const error = resultMessage.error ? new Error(resultMessage.error) : undefined;
        this.complete(resultMessage.databaseWriteJobId, error, resultMessage.result);
      }
    });
  }

  /**
   * Starts a periodic checker to timeout stale jobs
   */
  private startTimeoutChecker(): void {
    setInterval(() => {
      const now = Date.now();

      for (const [jobId, job] of this.pendingJobs) {
        if (now - job.timestamp > this.jobTimeout) {
          this.pendingJobs.delete(jobId);
          job.reject(new Error(`WriteQueue: Job ${jobId} timed out after ${this.jobTimeout}ms`));
        }
      }
    }, 5000); // Check every 5 seconds
  }
}

/**
 * Singleton WriteQueue instance for the application
 */
let writeQueueInstance: WriteQueue | null = null;

/**
 * Gets the singleton WriteQueue instance, creating it if necessary
 *
 * @param jobTimeout - Optional timeout for new instance creation
 * @returns The WriteQueue singleton instance
 */
export function getWriteQueue(jobTimeout?: number): WriteQueue {
  if (!writeQueueInstance) {
    writeQueueInstance = new WriteQueue(jobTimeout);
  }
  return writeQueueInstance;
}

/**
 * Resets the WriteQueue singleton (primarily for testing)
 */
export function resetWriteQueue(): void {
  if (writeQueueInstance) {
    writeQueueInstance.clearAllPending(new Error('WriteQueue reset'));
    writeQueueInstance = null;
  }
}

/**
 * Base Service Class
 *
 * Abstract base class that provides common functionality for all service classes.
 * Services should extend this class to inherit common utilities and patterns.
 */

// Logger types defined inline to avoid dependency on api types

/**
 * Logger interface for services
 */
export interface ServiceLogger {
  debug(message: string, context?: Record<string, unknown>): void;
  info(message: string, context?: Record<string, unknown>): void;
  warn(message: string, context?: Record<string, unknown>): void;
  error(message: string, error?: Error, context?: Record<string, unknown>): void;
}

/**
 * Simple console logger implementation
 */
class ConsoleLogger implements ServiceLogger {
  constructor(private readonly serviceName: string) {}

  private formatMessage(level: string, message: string, context?: Record<string, unknown>): string {
    const timestamp = new Date().toISOString();
    const contextStr = context !== undefined ? ` ${JSON.stringify(context)}` : '';
    return `[${timestamp}] [${level}] [${this.serviceName}] ${message}${contextStr}`;
  }

  /* eslint-disable no-console */
  debug(message: string, context?: Record<string, unknown>): void {
    console.log(this.formatMessage('DEBUG', message, context));
  }

  info(message: string, context?: Record<string, unknown>): void {
    console.log(this.formatMessage('INFO', message, context));
  }

  warn(message: string, context?: Record<string, unknown>): void {
    console.warn(this.formatMessage('WARN', message, context));
  }

  error(message: string, error?: Error, context?: Record<string, unknown>): void {
    const errorContext =
      error !== undefined ? { ...context, error: error.message, stack: error.stack } : context;
    console.error(this.formatMessage('ERROR', message, errorContext));
  }
  /* eslint-enable no-console */
}

/**
 * Service initialization options
 */
export interface ServiceOptions {
  logger?: ServiceLogger;
}

/**
 * Abstract base service class
 *
 * Provides:
 * - Structured logging
 * - Common utility methods
 * - Error handling patterns
 */
export abstract class BaseService {
  protected readonly logger: ServiceLogger;

  constructor(serviceName: string, options?: ServiceOptions) {
    this.logger = options?.logger ?? new ConsoleLogger(serviceName);
  }

  /**
   * Gets the current Unix timestamp in seconds
   */
  protected getCurrentTimestamp(): number {
    return Math.floor(Date.now() / 1000);
  }

  /**
   * Gets the current Unix timestamp in milliseconds
   */
  protected getCurrentTimestampMs(): number {
    return Date.now();
  }

  /**
   * Safely parses JSON with error handling
   *
   * @param json - JSON string to parse
   * @param fallback - Default value if parsing fails
   * @returns Parsed value or fallback
   */
  protected safeJsonParse<T>(json: string, fallback: T): T {
    try {
      return JSON.parse(json) as T;
    } catch {
      return fallback;
    }
  }

  /**
   * Wraps an async operation with error logging
   *
   * @param operation - Operation name for logging
   * @param fn - Async function to execute
   * @returns Promise with result or throws
   */
  protected async withErrorLogging<T>(operation: string, fn: () => T | Promise<T>): Promise<T> {
    try {
      return await fn();
    } catch (error) {
      this.logger.error(`${operation} failed`, error as Error);
      throw error;
    }
  }

  /**
   * Sanitize string by removing extra whitespace
   *
   * @param str - String to sanitize
   * @returns Sanitized string
   */
  protected sanitizeWhitespace(str: string): string {
    return str.replace(/\s+/g, ' ').trim();
  }

  /**
   * Generate a unique ID using similar pattern to existing video ID generation
   *
   * @param length - Length of the ID (default: 11)
   * @returns Generated unique ID
   */
  protected generateId(length: number = 11): string {
    const characters = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz_-';
    let id = '';
    let hyphenCount = 0;
    let underscoreCount = 0;

    for (let i = 0; i < length; ) {
      const randomChar = characters.charAt(Math.floor(Math.random() * characters.length));

      // Limit special characters
      if (randomChar === '-') {
        hyphenCount++;
        if (hyphenCount > 1) {
          continue;
        }
      } else if (randomChar === '_') {
        underscoreCount++;
        if (underscoreCount > 1) {
          continue;
        }
      }

      id += randomChar;
      i++;
    }

    return id;
  }

  /**
   * Delay execution for specified milliseconds
   *
   * @param ms - Milliseconds to delay
   * @returns Promise that resolves after delay
   */
  protected delay(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  /**
   * Retry an operation with exponential backoff
   *
   * @param operation - Operation name for logging
   * @param fn - Async function to retry
   * @param maxRetries - Maximum number of retries (default: 3)
   * @param baseDelay - Base delay in ms (default: 1000)
   * @returns Promise with result
   */
  protected async withRetry<T>(
    operation: string,
    fn: () => Promise<T>,
    maxRetries: number = 3,
    baseDelay: number = 1000
  ): Promise<T> {
    let lastError: Error | undefined;

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      try {
        return await fn();
      } catch (error) {
        lastError = error as Error;
        if (attempt < maxRetries) {
          const delayMs = baseDelay * Math.pow(2, attempt);
          this.logger.warn(`${operation} failed, retrying in ${delayMs}ms`, {
            attempt: attempt + 1,
            maxRetries,
            error: lastError.message,
          });
          await this.delay(delayMs);
        }
      }
    }

    this.logger.error(`${operation} failed after ${maxRetries} retries`, lastError);
    throw lastError as Error;
  }
}

/**
 * Indexer Service
 *
 * Service layer for communication with the MoarTube Indexer service.
 * Handles video indexing, node identification, and network updates.
 */
import axios, { type AxiosInstance, type AxiosError } from 'axios';

import { BaseService, type ServiceOptions } from './base.js';
import type {
  IIndexerService,
  VideoIndexData,
  RemoveFromIndexData,
  IndexerSubmitResult,
} from './interfaces.js';
import { getConfig } from '../config/index.js';

/**
 * Indexer response structure
 */
interface IndexerResponse {
  isError: boolean;
  message?: string;
  moarTubeTokenProof?: string;
}

/**
 * IndexerService class
 *
 * Handles all communication with the MoarTube Indexer:
 * - Adding/removing videos from the index
 * - Node identification and authentication
 * - Node personalization updates
 * - Network configuration updates
 */
export class IndexerService extends BaseService implements IIndexerService {
  private readonly httpClient: AxiosInstance;
  private readonly indexerUrl: string;

  constructor(options?: ServiceOptions) {
    super('IndexerService', options);

    const config = getConfig();
    const indexerConfig = config.appConfig.indexerConfig;
    this.indexerUrl = `${indexerConfig.httpProtocol}://${indexerConfig.host}:${indexerConfig.port}`;

    this.httpClient = axios.create({
      baseURL: this.indexerUrl,
      timeout: 30000,
    });
  }

  /**
   * Add a video to the index
   */
  addVideoToIndex(videoId: string): void {
    // This is a simplified version - full implementation would gather all video data
    // and call the indexer API
    this.logger.info('Adding video to index', { videoId });

    // The actual implementation would gather video data, node info, images, etc.
    // and submit to indexer. For now, we just log the intent.
    // Full implementation requires integration with VideoService to get data.
  }

  /**
   * Submit full video data to index
   */
  async submitVideoToIndex(data: VideoIndexData): Promise<IndexerSubmitResult> {
    try {
      const response = await this.httpClient.post<IndexerResponse>('/index/video/add', data);
      const result: IndexerSubmitResult = {
        isError: response.data.isError,
        statusCode: response.status,
      };
      if (response.data.message !== undefined) {
        result.message = response.data.message;
      }
      return result;
    } catch (error) {
      const axiosError = error as AxiosError<IndexerResponse>;

      // Handle 413 Request Entity Too Large specifically
      if (axiosError.response?.status === 413) {
        this.logger.warn('Video index submission too large', { videoId: data.videoId });
        return {
          isError: true,
          message:
            'The request size exceeded the 1MB limit. Try reducing the size of your node icon, avatar, and/or video preview images.',
          statusCode: 413,
        };
      }

      // Re-throw for other errors to be handled by withErrorLogging
      this.logger.error('Failed to submit video to index', error as Error, {
        videoId: data.videoId,
      });
      const result: IndexerSubmitResult = {
        isError: true,
        message: axiosError.response?.data?.message ?? (error as Error).message,
      };
      if (axiosError.response?.status !== undefined) {
        result.statusCode = axiosError.response.status;
      }
      return result;
    }
  }

  /**
   * Remove a video from the index
   */
  async removeVideoFromIndex(data: RemoveFromIndexData): Promise<void> {
    return this.withErrorLogging('removeVideoFromIndex', async () => {
      const response = await this.httpClient.post<IndexerResponse>('/index/video/remove', data);

      if (response.data.isError) {
        throw new Error(response.data.message ?? 'Failed to remove video from index');
      }

      this.logger.info('Video removed from index', { videoId: data.videoId });
    });
  }

  /**
   * Update video data in the index
   */
  async updateVideoIndex(data: Partial<VideoIndexData>): Promise<void> {
    return this.withErrorLogging('updateVideoIndex', async () => {
      await this.httpClient.post('/index/video/update', data);
      this.logger.info('Video index updated', { videoId: data.videoId });
    });
  }

  /**
   * Update node personalization (name)
   */
  async updateNodeName(name: string): Promise<void> {
    return this.withErrorLogging('updateNodeName', async () => {
      const config = getConfig();
      const nodeIdentification = config.nodeIdentification;

      if (!nodeIdentification) {
        throw new Error('Node not identified');
      }

      const data = {
        nodeName: name,
        moarTubeTokenProof: nodeIdentification.moarTubeTokenProof,
      };

      await this.httpClient.post('/index/node/personalize/nodeName', data);
      this.logger.info('Node name updated in index', { name });
    });
  }

  /**
   * Update node personalization (about)
   */
  async updateNodeAbout(about: string): Promise<void> {
    return this.withErrorLogging('updateNodeAbout', async () => {
      const config = getConfig();
      const nodeIdentification = config.nodeIdentification;

      if (!nodeIdentification) {
        throw new Error('Node not identified');
      }

      const data = {
        nodeAbout: about,
        moarTubeTokenProof: nodeIdentification.moarTubeTokenProof,
      };

      await this.httpClient.post('/index/node/personalize/nodeAbout', data);
      this.logger.info('Node about updated in index');
    });
  }

  /**
   * Update node personalization (ID)
   */
  async updateNodeId(nodeId: string): Promise<void> {
    return this.withErrorLogging('updateNodeId', async () => {
      const config = getConfig();
      const nodeIdentification = config.nodeIdentification;

      if (!nodeIdentification) {
        throw new Error('Node not identified');
      }

      const data = {
        nodeId,
        moarTubeTokenProof: nodeIdentification.moarTubeTokenProof,
      };

      await this.httpClient.post('/index/node/personalize/nodeId', data);
      this.logger.info('Node ID updated in index', { nodeId });
    });
  }

  /**
   * Update external network configuration
   */
  async updateExternalNetwork(
    publicNodeProtocol: string,
    publicNodeAddress: string,
    publicNodePort: string
  ): Promise<void> {
    return this.withErrorLogging('updateExternalNetwork', async () => {
      const config = getConfig();
      const nodeIdentification = config.nodeIdentification;

      if (!nodeIdentification) {
        throw new Error('Node not identified');
      }

      const data = {
        publicNodeProtocol,
        publicNodeAddress,
        publicNodePort,
        moarTubeTokenProof: nodeIdentification.moarTubeTokenProof,
      };

      await this.httpClient.post('/index/node/network/update', data);
      this.logger.info('Node network configuration updated in index');
    });
  }

  /**
   * Check indexer health/connectivity
   */
  async checkHealth(): Promise<boolean> {
    try {
      const response = await this.httpClient.get('/health', { timeout: 5000 });
      return response.status === 200;
    } catch {
      return false;
    }
  }

  /**
   * Get node identification from indexer
   */
  async getNodeIdentification(): Promise<{ moarTubeTokenProof: string }> {
    return this.withErrorLogging('getNodeIdentification', async () => {
      const response = await this.httpClient.get<{ moarTubeTokenProof: string }>(
        '/node/identification'
      );
      return response.data;
    });
  }

  /**
   * Refresh node identification
   */
  async refreshNodeIdentification(
    moarTubeTokenProof: string
  ): Promise<{ moarTubeTokenProof: string }> {
    return this.withErrorLogging('refreshNodeIdentification', async () => {
      const response = await this.httpClient.get<{ moarTubeTokenProof: string }>(
        '/node/identification/refresh',
        {
          params: { moarTubeTokenProof },
        }
      );
      return response.data;
    });
  }

  /**
   * Perform full node identification flow
   *
   * Gets or refreshes node identification with the MoarTube indexer
   */
  async performNodeIdentification(): Promise<void> {
    return this.withErrorLogging('performNodeIdentification', async () => {
      this.logger.info('Validating node to MoarTube network');

      const config = getConfig();
      const existingIdentification = config.nodeIdentification;

      // Create a mutable copy
      const nodeIdentification: { moarTubeTokenProof: string } = existingIdentification
        ? { moarTubeTokenProof: existingIdentification.moarTubeTokenProof }
        : { moarTubeTokenProof: '' };

      if (nodeIdentification.moarTubeTokenProof === '') {
        // Node is unidentified - get new identification
        this.logger.info('Node is unidentified, creating node identification');
        const result = await this.getNodeIdentification();
        nodeIdentification.moarTubeTokenProof = result.moarTubeTokenProof;
      } else {
        // Refresh existing identification
        this.logger.info('Node identification found, refreshing');
        const result = await this.refreshNodeIdentification(nodeIdentification.moarTubeTokenProof);
        nodeIdentification.moarTubeTokenProof = result.moarTubeTokenProof;
      }

      // Persist updated identification
      config.setNodeIdentification(nodeIdentification);

      this.logger.info('Node identification successful');
    });
  }
}

/**
 * Report Service
 *
 * Service layer for content reporting and moderation functionality.
 * Handles video and comment reports, archiving, and moderation workflows.
 */
import { BaseService, type ServiceOptions } from './base.js';
import type {
  IReportService,
  CreateVideoReportInput,
  CreateCommentReportInput,
} from './interfaces.js';
import type { ReportsVideosRepository } from '../database/repositories/reports-videos.js';
import type { ReportsCommentsRepository } from '../database/repositories/reports-comments.js';
import type { ReportsArchiveVideosRepository } from '../database/repositories/reports-archive-videos.js';
import type { ReportsArchiveCommentsRepository } from '../database/repositories/reports-archive-comments.js';
import type {
  DrizzleVideoReport,
  DrizzleCommentReport,
  DrizzleVideoReportArchive,
  DrizzleCommentReportArchive,
  DrizzleNewVideoReport,
  DrizzleNewCommentReport,
  DrizzleNewVideoReportArchive,
  DrizzleNewCommentReportArchive,
} from '../database/schema/index.js';
import type { PaginationOptions } from '../types/models.js';

/**
 * Report service dependencies
 */
export interface ReportServiceDependencies {
  videoReportRepository: ReportsVideosRepository;
  commentReportRepository: ReportsCommentsRepository;
  videoReportsArchiveRepository: ReportsArchiveVideosRepository;
  commentReportsArchiveRepository: ReportsArchiveCommentsRepository;
}

/**
 * ReportService class
 *
 * Handles all content reporting and moderation:
 * - Creating video and comment reports
 * - Managing report queues
 * - Archiving handled reports
 * - Report statistics
 */
export class ReportService extends BaseService implements IReportService {
  private readonly videoReportRepository: ReportsVideosRepository;
  private readonly commentReportRepository: ReportsCommentsRepository;
  private readonly videoReportsArchiveRepository: ReportsArchiveVideosRepository;
  private readonly commentReportsArchiveRepository: ReportsArchiveCommentsRepository;

  constructor(dependencies: ReportServiceDependencies, options?: ServiceOptions) {
    super('ReportService', options);
    this.videoReportRepository = dependencies.videoReportRepository;
    this.commentReportRepository = dependencies.commentReportRepository;
    this.videoReportsArchiveRepository = dependencies.videoReportsArchiveRepository;
    this.commentReportsArchiveRepository = dependencies.commentReportsArchiveRepository;
  }

  /**
   * Create a video report
   */
  async createVideoReport(data: CreateVideoReportInput): Promise<DrizzleVideoReport> {
    return this.withErrorLogging('createVideoReport', async () => {
      const timestamp = this.getCurrentTimestamp();

      const reportData: DrizzleNewVideoReport = {
        timestamp,
        videoTimestamp: data.videoTimestamp,
        videoId: data.videoId,
        email: data.email,
        type: data.type,
        message: data.message,
      };

      this.logger.info('Creating video report', {
        videoId: data.videoId,
        type: data.type,
      });

      return this.videoReportRepository.create(reportData);
    });
  }

  /**
   * Create a comment report
   */
  async createCommentReport(data: CreateCommentReportInput): Promise<DrizzleCommentReport> {
    return this.withErrorLogging('createCommentReport', async () => {
      const timestamp = this.getCurrentTimestamp();

      const reportData: DrizzleNewCommentReport = {
        timestamp,
        commentTimestamp: data.commentTimestamp,
        videoId: data.videoId,
        commentId: data.commentId,
        email: data.email,
        type: data.type,
        message: data.message,
      };

      this.logger.info('Creating comment report', {
        videoId: data.videoId,
        commentId: data.commentId,
        type: data.type,
      });

      return this.commentReportRepository.create(reportData);
    });
  }

  /**
   * Get all video reports
   */
  async getVideoReports(options?: PaginationOptions): Promise<DrizzleVideoReport[]> {
    return this.videoReportRepository.findAll(options);
  }

  /**
   * Get all comment reports
   */
  async getCommentReports(options?: PaginationOptions): Promise<DrizzleCommentReport[]> {
    return this.commentReportRepository.findAll(options);
  }

  /**
   * Get video reports for a specific video
   */
  async getVideoReportsForVideo(videoId: string): Promise<DrizzleVideoReport[]> {
    return this.videoReportRepository.findByVideoId(videoId);
  }

  /**
   * Get comment reports for a specific video
   */
  async getCommentReportsForVideo(videoId: string): Promise<DrizzleCommentReport[]> {
    return this.commentReportRepository.findByVideoId(videoId);
  }

  /**
   * Archive a video report (mark as handled)
   */
  async archiveVideoReport(reportId: number): Promise<DrizzleVideoReportArchive> {
    return this.withErrorLogging('archiveVideoReport', async () => {
      const report = await this.videoReportRepository.findById(reportId);
      if (!report) {
        throw new Error(`Video report not found: ${reportId}`);
      }

      // Create archive record
      const archiveData: DrizzleNewVideoReportArchive = {
        reportId: report.reportId,
        timestamp: report.timestamp,
        videoTimestamp: report.videoTimestamp,
        videoId: report.videoId,
        email: report.email,
        type: report.type,
        message: report.message,
      };

      const archived = await this.videoReportsArchiveRepository.create(archiveData);

      // Delete original report
      await this.videoReportRepository.delete(reportId);

      this.logger.info('Video report archived', { reportId, videoId: report.videoId });

      return archived;
    });
  }

  /**
   * Archive a comment report (mark as handled)
   */
  async archiveCommentReport(reportId: number): Promise<DrizzleCommentReportArchive> {
    return this.withErrorLogging('archiveCommentReport', async () => {
      const report = await this.commentReportRepository.findById(reportId);
      if (!report) {
        throw new Error(`Comment report not found: ${reportId}`);
      }

      // Create archive record
      const archiveData: DrizzleNewCommentReportArchive = {
        reportId: report.reportId,
        timestamp: report.timestamp,
        commentTimestamp: report.commentTimestamp,
        videoId: report.videoId,
        commentId: report.commentId,
        email: report.email,
        type: report.type,
        message: report.message,
      };

      const archived = await this.commentReportsArchiveRepository.create(archiveData);

      // Delete original report
      await this.commentReportRepository.delete(reportId);

      this.logger.info('Comment report archived', {
        reportId,
        videoId: report.videoId,
        commentId: report.commentId,
      });

      return archived;
    });
  }

  /**
   * Delete a video report
   */
  async deleteVideoReport(reportId: number): Promise<boolean> {
    return this.videoReportRepository.delete(reportId);
  }

  /**
   * Delete a comment report
   */
  async deleteCommentReport(reportId: number): Promise<boolean> {
    return this.commentReportRepository.delete(reportId);
  }

  /**
   * Get archived video reports
   */
  async getArchivedVideoReports(options?: PaginationOptions): Promise<DrizzleVideoReportArchive[]> {
    return this.videoReportsArchiveRepository.findAll(options);
  }

  /**
   * Get archived comment reports
   */
  async getArchivedCommentReports(
    options?: PaginationOptions
  ): Promise<DrizzleCommentReportArchive[]> {
    return this.commentReportsArchiveRepository.findAll(options);
  }

  /**
   * Delete archived video report
   */
  async deleteArchivedVideoReport(archiveId: number): Promise<boolean> {
    return this.videoReportsArchiveRepository.delete(archiveId);
  }

  /**
   * Delete archived comment report
   */
  async deleteArchivedCommentReport(archiveId: number): Promise<boolean> {
    return this.commentReportsArchiveRepository.delete(archiveId);
  }

  /**
   * Count total video reports
   */
  async countVideoReports(): Promise<number> {
    return this.videoReportRepository.count();
  }

  /**
   * Count total comment reports
   */
  async countCommentReports(): Promise<number> {
    return this.commentReportRepository.count();
  }

  /**
   * Get report summary statistics
   */
  async getReportStats(): Promise<{
    videoReports: number;
    commentReports: number;
    archivedVideoReports: number;
    archivedCommentReports: number;
  }> {
    const [videoReports, commentReports, archivedVideoReports, archivedCommentReports] =
      await Promise.all([
        this.countVideoReports(),
        this.countCommentReports(),
        this.videoReportsArchiveRepository.count(),
        this.commentReportsArchiveRepository.count(),
      ]);

    return {
      videoReports,
      commentReports,
      archivedVideoReports,
      archivedCommentReports,
    };
  }
}

/**
 * Settings Service
