/**
 * Storage Service
 *
 * Unified storage abstraction layer supporting both filesystem and S3 storage modes.
 * Provides a consistent interface for file operations regardless of storage backend.
 */
import fs from 'node:fs';
import path from 'node:path';
import type { Readable } from 'node:stream';

import {
  S3Client,
  GetObjectCommand,
  PutObjectCommand,
  DeleteObjectCommand,
  HeadObjectCommand,
  ListObjectsV2Command,
  CopyObjectCommand,
  DeleteObjectsCommand,
  type S3ClientConfig,
} from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';

import { BaseService, type ServiceOptions } from './base.js';
import type { IStorageService, StorageMode, FileMetadata } from './interfaces.js';
import { getConfig } from '../config/index.js';

/**
 * S3 configuration for the storage service
 */
export interface S3Config {
  bucketName: string;
  s3ProviderClientConfig: S3ClientConfig;
}

/**
 * StorageService class
 *
 * Provides unified file storage operations for:
 * - Filesystem storage (local disk)
 * - S3-compatible storage (AWS S3, MinIO, DigitalOcean Spaces, etc.)
 */
export class StorageService extends BaseService implements IStorageService {
  private s3Client: S3Client | null = null;
  private s3Config: S3Config | null = null;

  constructor(options?: ServiceOptions) {
    super('StorageService', options);
    this.initializeS3Client();
  }

  /**
   * Initialize S3 client if configured
   */
  private initializeS3Client(): void {
    try {
      const config = getConfig();
      const storageConfig = config.nodeSettings.storageConfig;

      if (storageConfig.storageMode === 's3provider' && storageConfig.s3Config) {
        this.s3Config = {
          bucketName: storageConfig.s3Config.bucketName,
          s3ProviderClientConfig: storageConfig.s3Config.s3ProviderClientConfig as S3ClientConfig,
        };
        this.s3Client = new S3Client(this.s3Config.s3ProviderClientConfig);
        this.logger.info('S3 client initialized', {
          bucketName: this.s3Config.bucketName,
        });
      }
    } catch (error) {
      this.logger.debug('S3 client not configured', {
        error: (error as Error).message,
      });
    }
  }

  /**
   * Get current storage mode
   */
  getStorageMode(): StorageMode {
    const config = getConfig();
    return config.nodeSettings.storageConfig.storageMode;
  }

  /**
   * Save a file to storage
   */
  async saveFile(key: string, data: Buffer, contentType?: string): Promise<void> {
    return this.withErrorLogging('saveFile', async () => {
      if (this.getStorageMode() === 'filesystem') {
        this.saveToFilesystem(key, data);
      } else {
        await this.saveToS3(key, data, contentType);
      }
    });
  }

  /**
   * Get a file from storage
   */
  async getFile(key: string): Promise<Buffer> {
    return this.withErrorLogging('getFile', async () => {
      if (this.getStorageMode() === 'filesystem') {
        return this.getFromFilesystem(key);
      } else {
        return this.getFromS3(key);
      }
    });
  }

  /**
   * Get a file stream from storage
   */
  async getFileStream(key: string): Promise<NodeJS.ReadableStream> {
    if (this.getStorageMode() === 'filesystem') {
      const filePath = this.resolveFilePath(key);
      return fs.createReadStream(filePath);
    } else {
      return this.getStreamFromS3(key);
    }
  }

  /**
   * Delete a file from storage
   */
  async deleteFile(key: string): Promise<boolean> {
    return this.withErrorLogging('deleteFile', async () => {
      if (this.getStorageMode() === 'filesystem') {
        return this.deleteFromFilesystem(key);
      } else {
        return this.deleteFromS3(key);
      }
    });
  }

  /**
   * Check if a file exists
   */
  async fileExists(key: string): Promise<boolean> {
    try {
      if (this.getStorageMode() === 'filesystem') {
        const filePath = this.resolveFilePath(key);
        return fs.existsSync(filePath);
      } else {
        return this.existsInS3(key);
      }
    } catch {
      return false;
    }
  }

  /**
   * Get file metadata
   */
  async getFileMetadata(key: string): Promise<FileMetadata | null> {
    try {
      if (this.getStorageMode() === 'filesystem') {
        return this.getFilesystemMetadata(key);
      } else {
        return this.getS3Metadata(key);
      }
    } catch {
      return null;
    }
  }

  /**
   * List files in a directory/prefix
   */
  async listFiles(prefix: string): Promise<FileMetadata[]> {
    return this.withErrorLogging('listFiles', async () => {
      if (this.getStorageMode() === 'filesystem') {
        return this.listFilesystemFiles(prefix);
      } else {
        return this.listS3Files(prefix);
      }
    });
  }

  /**
   * Delete a directory recursively
   */
  async deleteDirectory(prefix: string): Promise<number> {
    return this.withErrorLogging('deleteDirectory', async () => {
      if (this.getStorageMode() === 'filesystem') {
        return this.deleteFilesystemDirectory(prefix);
      } else {
        return this.deleteS3Directory(prefix);
      }
    });
  }

  /**
   * Copy a file
   */
  async copyFile(sourceKey: string, destKey: string): Promise<void> {
    return this.withErrorLogging('copyFile', async () => {
      if (this.getStorageMode() === 'filesystem') {
        this.copyFilesystemFile(sourceKey, destKey);
      } else {
        await this.copyS3File(sourceKey, destKey);
      }
    });
  }

  /**
   * Get presigned URL for direct access (S3 only)
   */
  async getPresignedUrl(key: string, expiresIn: number = 3600): Promise<string> {
    if (this.getStorageMode() !== 's3provider' || !this.s3Client || !this.s3Config) {
      throw new Error('Presigned URLs are only available for S3 storage');
    }

    const command = new GetObjectCommand({
      Bucket: this.s3Config.bucketName,
      Key: key,
    });

    return getSignedUrl(this.s3Client, command, { expiresIn });
  }

  // ============================================================================
  // Filesystem Storage Methods
  // ============================================================================

  private resolveFilePath(key: string): string {
    const config = getConfig();
    // Key is relative to data directory or videos directory based on prefix
    if (key.startsWith('external/videos/')) {
      return path.join(config.paths.videosDirectoryPath, key.replace('external/videos/', ''));
    }
    return path.join(config.paths.dataDirectoryPath, key);
  }

  private saveToFilesystem(key: string, data: Buffer): void {
    const filePath = this.resolveFilePath(key);
    const dir = path.dirname(filePath);

    // Ensure directory exists
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }

    fs.writeFileSync(filePath, data);
  }

  private getFromFilesystem(key: string): Buffer {
    const filePath = this.resolveFilePath(key);
    return fs.readFileSync(filePath);
  }

  private deleteFromFilesystem(key: string): boolean {
    const filePath = this.resolveFilePath(key);
    if (fs.existsSync(filePath)) {
      fs.rmSync(filePath, { force: true });
      return true;
    }
    return false;
  }

  private getFilesystemMetadata(key: string): FileMetadata | null {
    const filePath = this.resolveFilePath(key);
    if (!fs.existsSync(filePath)) {
      return null;
    }

    const stats = fs.statSync(filePath);
    return {
      key,
      size: stats.size,
      lastModified: stats.mtime,
    };
  }

  private listFilesystemFiles(prefix: string): FileMetadata[] {
    const dirPath = this.resolveFilePath(prefix);
    if (!fs.existsSync(dirPath) || !fs.statSync(dirPath).isDirectory()) {
      return [];
    }

    const files: FileMetadata[] = [];
    const entries = fs.readdirSync(dirPath, { withFileTypes: true });

    for (const entry of entries) {
      if (entry.isFile()) {
        const filePath = path.join(dirPath, entry.name);
        const stats = fs.statSync(filePath);
        files.push({
          key: path.join(prefix, entry.name),
          size: stats.size,
          lastModified: stats.mtime,
        });
      }
    }

    return files;
  }

  private deleteFilesystemDirectory(prefix: string): number {
    const dirPath = this.resolveFilePath(prefix);
    if (!fs.existsSync(dirPath)) {
      return 0;
    }

    // Count files before deletion
    let count = 0;
    const countFiles = (dir: string): void => {
      const entries = fs.readdirSync(dir, { withFileTypes: true });
      for (const entry of entries) {
        if (entry.isFile()) {
          count++;
        } else if (entry.isDirectory()) {
          countFiles(path.join(dir, entry.name));
        }
      }
    };

    countFiles(dirPath);
    fs.rmSync(dirPath, { recursive: true, force: true });
    return count;
  }

  private copyFilesystemFile(sourceKey: string, destKey: string): void {
    const sourcePath = this.resolveFilePath(sourceKey);
    const destPath = this.resolveFilePath(destKey);

    const destDir = path.dirname(destPath);
    if (!fs.existsSync(destDir)) {
      fs.mkdirSync(destDir, { recursive: true });
    }

    fs.copyFileSync(sourcePath, destPath);
  }

  // ============================================================================
  // S3 Storage Methods
  // ============================================================================

  private ensureS3Client(): { client: S3Client; config: S3Config } {
    if (!this.s3Client || !this.s3Config) {
      throw new Error('S3 client not configured');
    }
    return { client: this.s3Client, config: this.s3Config };
  }

  private async saveToS3(key: string, data: Buffer, contentType?: string): Promise<void> {
    const { client, config } = this.ensureS3Client();

    await client.send(
      new PutObjectCommand({
        Bucket: config.bucketName,
        Key: key,
        Body: data,
        ContentType: contentType,
      })
    );
  }

  private async getFromS3(key: string): Promise<Buffer> {
    const { client, config } = this.ensureS3Client();

    const response = await client.send(
      new GetObjectCommand({
        Bucket: config.bucketName,
        Key: key,
      })
    );

    return this.streamToBuffer(response.Body as Readable);
  }

  private async getStreamFromS3(key: string): Promise<NodeJS.ReadableStream> {
    const { client, config } = this.ensureS3Client();

    const response = await client.send(
      new GetObjectCommand({
        Bucket: config.bucketName,
        Key: key,
      })
    );

    return response.Body as NodeJS.ReadableStream;
  }

  private async deleteFromS3(key: string): Promise<boolean> {
    const { client, config } = this.ensureS3Client();

    try {
      await client.send(
        new DeleteObjectCommand({
          Bucket: config.bucketName,
          Key: key,
        })
      );
      return true;
    } catch {
      return false;
    }
  }

  private async existsInS3(key: string): Promise<boolean> {
    const { client, config } = this.ensureS3Client();

    try {
      await client.send(
        new HeadObjectCommand({
          Bucket: config.bucketName,
          Key: key,
        })
      );
      return true;
    } catch {
      return false;
    }
  }

  private async getS3Metadata(key: string): Promise<FileMetadata | null> {
    const { client, config } = this.ensureS3Client();

    try {
      const response = await client.send(
        new HeadObjectCommand({
          Bucket: config.bucketName,
          Key: key,
        })
      );

      return {
        key,
        size: response.ContentLength ?? 0,
        lastModified: response.LastModified ?? new Date(),
        contentType: response.ContentType ?? 'application/octet-stream',
      };
    } catch {
      return null;
    }
  }

  private async listS3Files(prefix: string): Promise<FileMetadata[]> {
    const { client, config } = this.ensureS3Client();

    const files: FileMetadata[] = [];
    let continuationToken: string | undefined;
    let isTruncated = true;

    while (isTruncated) {
      const response = await client.send(
        new ListObjectsV2Command({
          Bucket: config.bucketName,
          Prefix: prefix,
          ContinuationToken: continuationToken,
        })
      );

      if (response.Contents !== undefined) {
        for (const obj of response.Contents) {
          if (obj.Key !== undefined && obj.Key !== '') {
            files.push({
              key: obj.Key,
              size: obj.Size ?? 0,
              lastModified: obj.LastModified ?? new Date(),
            });
          }
        }
      }

      isTruncated = response.IsTruncated ?? false;
      continuationToken = response.NextContinuationToken;
    }

    return files;
  }

  private async deleteS3Directory(prefix: string): Promise<number> {
    const { client, config } = this.ensureS3Client();

    const files = await this.listS3Files(prefix);
    if (files.length === 0) {
      return 0;
    }

    // Delete in batches of 1000 (S3 limit)
    const batchSize = 1000;
    for (let i = 0; i < files.length; i += batchSize) {
      const batch = files.slice(i, i + batchSize);
      await client.send(
        new DeleteObjectsCommand({
          Bucket: config.bucketName,
          Delete: {
            Objects: batch.map((f) => ({ Key: f.key })),
          },
        })
      );
    }

    return files.length;
  }

  private async copyS3File(sourceKey: string, destKey: string): Promise<void> {
    const { client, config } = this.ensureS3Client();

    await client.send(
      new CopyObjectCommand({
        Bucket: config.bucketName,
        CopySource: `${config.bucketName}/${sourceKey}`,
        Key: destKey,
      })
    );
  }

  private async streamToBuffer(stream: Readable): Promise<Buffer> {
    return new Promise((resolve, reject) => {
      const chunks: Buffer[] = [];
      stream.on('data', (chunk: Buffer) => chunks.push(chunk));
      stream.on('end', () => { resolve(Buffer.concat(chunks)); });
      stream.on('error', reject);
    });
  }
}

/**
 * Videos Service
 *
 * Service layer for video-related business logic including CRUD operations,
 * publishing workflows, and metadata management.
 */
import fs from 'node:fs';
import path from 'node:path';

import { BaseService, type ServiceOptions } from './base.js';
import type {
  IVideoService,
  GetVideosOptions,
  CreateVideoInput,
  UpdateVideoInput,
  IStorageService,
  IWebSocketService,
  ICloudflareService,
  IIndexerService,
  VideoWatchData,
  VideoSource,
  SourcesFormatsAndResolutions,
  VideoPermissions,
  VideoData,
  AddToIndexOptions,
  AddToIndexResult,
  VideoIndexData,
} from './interfaces.js';
import type { VideosRepository } from '../database/repositories/videos.js';
import type { CommentsRepository } from '../database/repositories/comments.js';
import type { DrizzleVideo, DrizzleNewVideo } from '../database/schema/index.js';
import type { PaginatedResult } from '../types/models.js';
import { getConfig } from '../config/index.js';

/**
 * Videos service dependencies
 */
export interface VideosServiceDependencies {
  videoRepository: VideosRepository;
  commentRepository?: CommentsRepository;
  storageService?: IStorageService;
  websocketService?: IWebSocketService;
  cloudflareService?: ICloudflareService;
  indexerService?: IIndexerService;
}

/**
 * VideosService class
 *
 * Handles all video-related business logic including:
 * - Video CRUD operations
 * - Import/export workflows
 * - Publishing management
 * - View/like/dislike tracking
 * - Index management
 */
export class VideosService extends BaseService implements IVideoService {
  private readonly videoRepository: VideosRepository;
  private readonly commentRepository: CommentsRepository | undefined;
  private readonly storageService: IStorageService | undefined;
  private readonly websocketService: IWebSocketService | undefined;
  private readonly cloudflareService: ICloudflareService | undefined;
  private readonly indexerService: IIndexerService | undefined;

  // Debounced view counter - tracks pending views per video
  private readonly pendingViews: Map<string, number> = new Map();
  private readonly viewTimers: Map<string, ReturnType<typeof setTimeout>> = new Map();
  private static readonly VIEW_DEBOUNCE_MS = 500;

  constructor(dependencies: VideosServiceDependencies, options?: ServiceOptions) {
    super('VideosService', options);
    this.videoRepository = dependencies.videoRepository;
    this.commentRepository = dependencies.commentRepository;
    this.storageService = dependencies.storageService;
    this.websocketService = dependencies.websocketService;
    this.cloudflareService = dependencies.cloudflareService;
    this.indexerService = dependencies.indexerService;
  }

  /**
   * Get a single video by ID
   */
  async getVideo(videoId: string): Promise<DrizzleVideo | null> {
    return this.withErrorLogging('getVideo', async () => {
      return this.videoRepository.findById(videoId);
    });
  }

  /**
   * Get videos with filtering and pagination
   */
  async getVideos(options?: GetVideosOptions): Promise<PaginatedResult<DrizzleVideo>> {
    return this.withErrorLogging('getVideos', async () => {
      const limit = options?.limit ?? 20;
      const offset = options?.offset ?? 0;

      // Build query options, omitting undefined values
      const queryOptions: {
        limit: number;
        offset: number;
        sortBy?: 'creation_timestamp' | 'views' | 'likes' | 'title';
        sortDirection?: 'asc' | 'desc';
        isPublished?: boolean;
        isStreaming?: boolean;
        isFinalized?: boolean;
        search?: string;
      } = { limit, offset };

      if (options?.sortBy !== undefined) {
        queryOptions.sortBy = options.sortBy;
      }
      if (options?.sortDirection !== undefined) {
        queryOptions.sortDirection = options.sortDirection;
      }
      if (options?.isPublished !== undefined) {
        queryOptions.isPublished = options.isPublished;
      }
      if (options?.isStreaming !== undefined) {
        queryOptions.isStreaming = options.isStreaming;
      }
      if (options?.isFinalized !== undefined) {
        queryOptions.isFinalized = options.isFinalized;
      }
      if (options?.search !== undefined) {
        queryOptions.search = options.search;
      }

      // Query videos with filters
      const videos = await this.videoRepository.findAll(queryOptions);

      // Build count options, omitting undefined values
      const countOptions: {
        isPublished?: boolean;
        isStreaming?: boolean;
        isFinalized?: boolean;
        search?: string;
      } = {};

      if (options?.isPublished !== undefined) {
        countOptions.isPublished = options.isPublished;
      }
      if (options?.isStreaming !== undefined) {
        countOptions.isStreaming = options.isStreaming;
      }
      if (options?.isFinalized !== undefined) {
        countOptions.isFinalized = options.isFinalized;
      }
      if (options?.search !== undefined) {
        countOptions.search = options.search;
      }

      // Get total count for pagination
      const total = await this.videoRepository.count(countOptions);

      return {
        data: videos,
        total,
        count: videos.length,
        offset,
        limit,
        hasMore: offset + videos.length < total,
      };
    });
  }

  /**
   * Create a new video (import)
   *
   * Creates video record and sets up storage directories
   */
  async createVideo(data: CreateVideoInput): Promise<{ videoId: string }> {
    return this.withErrorLogging('createVideo', async () => {
      // Generate unique video ID
      const videoId = await this.generateUniqueVideoId();
      const creationTimestamp = this.getCurrentTimestampMs();

      // Sanitize input
      const tagsSanitized = this.sanitizeWhitespace(data.tags);

      // Initialize outputs structure
      const outputs = JSON.stringify({ m3u8: [], mp4: [], webm: [], ogv: [] });
      const meta = JSON.stringify({});

      this.logger.info('Creating new video', { videoId, title: data.title });

      // Create storage directories if using filesystem
      this.createVideoStorageDirectories(videoId);

      // Create video record
      const videoData: DrizzleNewVideo = {
        videoId,
        sourceFileExtension: '',
        title: data.title,
        description: data.description,
        tags: tagsSanitized,
        lengthSeconds: 0,
        lengthTimestamp: '',
        views: 0,
        comments: 0,
        likes: 0,
        dislikes: 0,
        bandwidth: 0,
        isImporting: true,
        isImported: false,
        isPublishing: false,
        isPublished: false,
        isStreaming: false,
        isStreamed: false,
        isStreamRecordedRemotely: false,
        isStreamRecordedLocally: false,
        isLive: false,
        isIndexing: false,
        isIndexed: false,
        isIndexOutdated: false,
        isError: false,
        isFinalized: false,
        isHidden: false,
        isPassworded: false,
        password: '',
        isCommentsEnabled: true,
        isLikesEnabled: true,
        isDislikesEnabled: true,
        isReportsEnabled: true,
        isLiveChatEnabled: true,
        outputs,
        meta,
        creationTimestamp,
      };

      await this.videoRepository.create(videoData);

      // Broadcast video creation event
      this.broadcastVideoEvent('video_data', {
        videoId,
        thumbnail: '',
        title: data.title,
        description: data.description,
        tags: tagsSanitized,
        lengthSeconds: 0,
        lengthTimestamp: '',
        views: 0,
        comments: 0,
        likes: 0,
        dislikes: 0,
        bandwidth: 0,
        isImporting: 1,
        isImported: 0,
        isPublishing: 0,
        isPublished: 0,
        isLive: 0,
        isStreaming: 0,
        isStreamed: 0,
        isStreamRecordedRemotely: 0,
        isStreamRecordedLocally: 0,
        isIndexed: 0,
        isIndexing: 0,
        isIndexOutdated: 0,
        isError: 0,
        isFinalized: 0,
        meta,
        creationTimestamp,
      });

      return { videoId };
    });
  }

  /**
   * Update video metadata
   */
  async updateVideo(videoId: string, data: UpdateVideoInput): Promise<DrizzleVideo | null> {
    return this.withErrorLogging('updateVideo', async () => {
      const existingVideo = await this.videoRepository.findById(videoId);
      if (!existingVideo) {
        return null;
      }

      // Build update object with only provided fields
      const updates: Partial<DrizzleNewVideo> = {};

      if (data.title !== undefined) {
        updates.title = data.title;
      }
      if (data.description !== undefined) {
        updates.description = data.description;
      }
      if (data.tags !== undefined) {
        updates.tags = this.sanitizeWhitespace(data.tags);
      }
      if (data.isPublished !== undefined) {
        updates.isPublished = data.isPublished;
      }
      if (data.isHidden !== undefined) {
        updates.isHidden = data.isHidden;
      }
      if (data.isPassworded !== undefined) {
        updates.isPassworded = data.isPassworded;
      }
      if (data.password !== undefined) {
        updates.password = data.password;
      }
      if (data.isCommentsEnabled !== undefined) {
        updates.isCommentsEnabled = data.isCommentsEnabled;
      }
      if (data.isLikesEnabled !== undefined) {
        updates.isLikesEnabled = data.isLikesEnabled;
      }
      if (data.isDislikesEnabled !== undefined) {
        updates.isDislikesEnabled = data.isDislikesEnabled;
      }
      if (data.isReportsEnabled !== undefined) {
        updates.isReportsEnabled = data.isReportsEnabled;
      }
      if (data.isLiveChatEnabled !== undefined) {
        updates.isLiveChatEnabled = data.isLiveChatEnabled;
      }

      // Mark index as outdated if metadata changed and video is indexed
      if (
        existingVideo.isIndexed &&
        (data.title !== undefined || data.description !== undefined || data.tags !== undefined)
      ) {
        updates.isIndexOutdated = true;
      }

      this.logger.debug('Updating video', { videoId, fields: Object.keys(updates) });

      const updatedVideo = await this.videoRepository.update(videoId, updates);

      // Purge Cloudflare cache after update
      if (this.cloudflareService) {
        try {
          await this.cloudflareService.purgeEmbedVideoPages([videoId]);
          await this.cloudflareService.purgeWatchPages([videoId]);
          await this.cloudflareService.purgeNodePage();
        } catch (error) {
          this.logger.warn('Failed to purge Cloudflare cache after video update', {
            videoId,
            error,
          });
        }
      }

      return updatedVideo;
    });
  }

  /**
   * Delete a video and all associated data
   */
  async deleteVideo(videoId: string): Promise<boolean> {
    return this.withErrorLogging('deleteVideo', async () => {
      const video = await this.videoRepository.findById(videoId);
      if (!video) {
        return false;
      }

      this.logger.info('Deleting video', { videoId });

      // Delete comments for the video
      if (this.commentRepository) {
        await this.commentRepository.deleteByVideoId(videoId);
      }

      // Delete storage directories
      await this.deleteVideoStorageDirectories(videoId);

      // Purge Cloudflare cache before deletion
      if (this.cloudflareService) {
        try {
          await this.cloudflareService.purgeNodePage();
          await this.cloudflareService.purgeEmbedVideoPages([videoId]);
          await this.cloudflareService.purgeAdaptiveVideos(videoId);
          await this.cloudflareService.purgeProgressiveVideos(videoId);
          await this.cloudflareService.purgeAllWatchPages();
          await this.cloudflareService.purgeVideoThumbnailImages([videoId]);
          await this.cloudflareService.purgeVideoPreviewImages([videoId]);
          await this.cloudflareService.purgeVideoPosterImages([videoId]);
        } catch (error) {
          this.logger.warn('Failed to purge Cloudflare cache during video deletion', {
            videoId,
            error,
          });
        }
      }

      // Delete video record
      return this.videoRepository.delete(videoId);
    });
  }

  /**
   * Mark video as importing
   */
  async setImporting(videoId: string, isImporting: boolean): Promise<void> {
    await this.videoRepository.update(videoId, { isImporting });
  }

  /**
   * Mark video as imported (import complete)
   */
  async setImported(videoId: string): Promise<void> {
    await this.videoRepository.update(videoId, {
      isImporting: false,
      isImported: true,
    });
  }

  /**
   * Mark video as publishing
   */
  async setPublishing(videoId: string, isPublishing: boolean): Promise<void> {
