/**
 * Filesystem Utilities
 *
 * Provides utility functions for filesystem operations including
 * directory management, file reading/writing, and JSON handling.
 */

import * as fs from 'node:fs';
import * as path from 'node:path';
import { promisify } from 'node:util';

// Promisified fs functions
const fsAccess = promisify(fs.access);
const fsMkdir = promisify(fs.mkdir);
const fsReadFile = promisify(fs.readFile);
const fsWriteFile = promisify(fs.writeFile);
const fsRm = promisify(fs.rm);
const fsReaddir = promisify(fs.readdir);
const fsStat = promisify(fs.stat);
const fsUnlink = promisify(fs.unlink);

/**
 * Filesystem error types
 */
export class FilesystemError extends Error {
  constructor(
    message: string,
    public readonly code: string,
    public readonly path: string
  ) {
    super(message);
    this.name = 'FilesystemError';
  }
}

// ============================================
// Directory Operations
// ============================================

/**
 * Check if a path exists
 * @param targetPath - Path to check
 */
export async function pathExists(targetPath: string): Promise<boolean> {
  try {
    await fsAccess(targetPath);
    return true;
  } catch {
    return false;
  }
}

/**
 * Check if a path exists (synchronous)
 * @param targetPath - Path to check
 */
export function pathExistsSync(targetPath: string): boolean {
  return fs.existsSync(targetPath);
}

/**
 * Ensure a directory exists, creating it if necessary
 * @param dirPath - Directory path to ensure
 */
export async function ensureDirectory(dirPath: string): Promise<void> {
  try {
    await fsMkdir(dirPath, { recursive: true });
  } catch (error) {
    const fsError = error as NodeJS.ErrnoException;
    if (fsError.code !== 'EEXIST') {
      throw new FilesystemError(
        `Failed to create directory: ${fsError.message}`,
        fsError.code ?? 'UNKNOWN',
        dirPath
      );
    }
  }
}

/**
 * Ensure a directory exists (synchronous)
 * @param dirPath - Directory path to ensure
 */
export function ensureDirectorySync(dirPath: string): void {
  try {
    fs.mkdirSync(dirPath, { recursive: true });
  } catch (error) {
    const fsError = error as NodeJS.ErrnoException;
    if (fsError.code !== 'EEXIST') {
      throw new FilesystemError(
        `Failed to create directory: ${fsError.message}`,
        fsError.code ?? 'UNKNOWN',
        dirPath
      );
    }
  }
}

/**
 * Delete a directory recursively
 * @param dirPath - Directory path to delete
 */
export async function deleteDirectory(dirPath: string): Promise<void> {
  try {
    await fsRm(dirPath, { recursive: true, force: true });
  } catch (error) {
    const fsError = error as NodeJS.ErrnoException;
    throw new FilesystemError(
      `Failed to delete directory: ${fsError.message}`,
      fsError.code ?? 'UNKNOWN',
      dirPath
    );
  }
}

/**
 * Delete a directory recursively (synchronous)
 * @param dirPath - Directory path to delete
 */
export function deleteDirectorySync(dirPath: string): void {
  try {
    fs.rmSync(dirPath, { recursive: true, force: true });
  } catch (error) {
    const fsError = error as NodeJS.ErrnoException;
    throw new FilesystemError(
      `Failed to delete directory: ${fsError.message}`,
      fsError.code ?? 'UNKNOWN',
      dirPath
    );
  }
}

/**
 * List directory contents
 * @param dirPath - Directory path to list
 */
export async function listDirectory(dirPath: string): Promise<string[]> {
  try {
    return await fsReaddir(dirPath);
  } catch (error) {
    const fsError = error as NodeJS.ErrnoException;
    throw new FilesystemError(
      `Failed to list directory: ${fsError.message}`,
      fsError.code ?? 'UNKNOWN',
      dirPath
    );
  }
}

/**
 * List directory contents (synchronous)
 * @param dirPath - Directory path to list
 */
export function listDirectorySync(dirPath: string): string[] {
  try {
    return fs.readdirSync(dirPath);
  } catch (error) {
    const fsError = error as NodeJS.ErrnoException;
    throw new FilesystemError(
      `Failed to list directory: ${fsError.message}`,
      fsError.code ?? 'UNKNOWN',
      dirPath
    );
  }
}

// ============================================
// File Operations
// ============================================

/**
 * Read a file as string
 * @param filePath - Path to file
 * @param encoding - File encoding (default: utf8)
 */
export async function readFile(
  filePath: string,
  encoding: BufferEncoding = 'utf8'
): Promise<string> {
  try {
    return await fsReadFile(filePath, encoding);
  } catch (error) {
    const fsError = error as NodeJS.ErrnoException;
    throw new FilesystemError(
      `Failed to read file: ${fsError.message}`,
      fsError.code ?? 'UNKNOWN',
      filePath
    );
  }
}

/**
 * Read a file as string (synchronous)
 * @param filePath - Path to file
 * @param encoding - File encoding (default: utf8)
 */
export function readFileSync(filePath: string, encoding: BufferEncoding = 'utf8'): string {
  try {
    return fs.readFileSync(filePath, encoding);
  } catch (error) {
    const fsError = error as NodeJS.ErrnoException;
    throw new FilesystemError(
      `Failed to read file: ${fsError.message}`,
      fsError.code ?? 'UNKNOWN',
      filePath
    );
  }
}

/**
 * Read a file as Buffer
 * @param filePath - Path to file
 */
export async function readFileBuffer(filePath: string): Promise<Buffer> {
  try {
    return await fsReadFile(filePath);
  } catch (error) {
    const fsError = error as NodeJS.ErrnoException;
    throw new FilesystemError(
      `Failed to read file: ${fsError.message}`,
      fsError.code ?? 'UNKNOWN',
      filePath
    );
  }
}

/**
 * Read a file as Buffer (synchronous)
 * @param filePath - Path to file
 */
export function readFileBufferSync(filePath: string): Buffer {
  try {
    return fs.readFileSync(filePath);
  } catch (error) {
    const fsError = error as NodeJS.ErrnoException;
    throw new FilesystemError(
      `Failed to read file: ${fsError.message}`,
      fsError.code ?? 'UNKNOWN',
      filePath
    );
  }
}

/**
 * Write content to a file
 * @param filePath - Path to file
 * @param content - Content to write
 * @param encoding - File encoding (default: utf8)
 */
export async function writeFile(
  filePath: string,
  content: string | Buffer,
  encoding: BufferEncoding = 'utf8'
): Promise<void> {
  try {
    // Ensure parent directory exists
    const dirPath = path.dirname(filePath);
    await ensureDirectory(dirPath);

    await fsWriteFile(filePath, content, encoding);
  } catch (error) {
    if (error instanceof FilesystemError) {
      throw error;
    }
    const fsError = error as NodeJS.ErrnoException;
    throw new FilesystemError(
      `Failed to write file: ${fsError.message}`,
      fsError.code ?? 'UNKNOWN',
      filePath
    );
  }
}

/**
 * Write content to a file (synchronous)
 * @param filePath - Path to file
 * @param content - Content to write
 * @param encoding - File encoding (default: utf8)
 */
export function writeFileSync(
  filePath: string,
  content: string | Buffer,
  encoding: BufferEncoding = 'utf8'
): void {
  try {
    // Ensure parent directory exists
    const dirPath = path.dirname(filePath);
    ensureDirectorySync(dirPath);

    fs.writeFileSync(filePath, content, encoding);
  } catch (error) {
    if (error instanceof FilesystemError) {
      throw error;
    }
    const fsError = error as NodeJS.ErrnoException;
    throw new FilesystemError(
      `Failed to write file: ${fsError.message}`,
      fsError.code ?? 'UNKNOWN',
      filePath
    );
  }
}

/**
 * Delete a file
 * @param filePath - Path to file
 */
export async function deleteFile(filePath: string): Promise<void> {
  try {
    await fsUnlink(filePath);
  } catch (error) {
    const fsError = error as NodeJS.ErrnoException;
    // Ignore if file doesn't exist
    if (fsError.code === 'ENOENT') {
      return;
    }
    throw new FilesystemError(
      `Failed to delete file: ${fsError.message}`,
      fsError.code ?? 'UNKNOWN',
      filePath
    );
  }
}

/**
 * Delete a file (synchronous)
 * @param filePath - Path to file
 */
export function deleteFileSync(filePath: string): void {
  try {
    fs.unlinkSync(filePath);
  } catch (error) {
    const fsError = error as NodeJS.ErrnoException;
    // Ignore if file doesn't exist
    if (fsError.code === 'ENOENT') {
      return;
    }
    throw new FilesystemError(
      `Failed to delete file: ${fsError.message}`,
      fsError.code ?? 'UNKNOWN',
      filePath
    );
  }
}

/**
 * Get file stats
 * @param filePath - Path to file
 */
export async function getFileStats(filePath: string): Promise<fs.Stats> {
  try {
    return await fsStat(filePath);
  } catch (error) {
    const fsError = error as NodeJS.ErrnoException;
    throw new FilesystemError(
      `Failed to get file stats: ${fsError.message}`,
      fsError.code ?? 'UNKNOWN',
      filePath
    );
  }
}

/**
 * Get file stats (synchronous)
 * @param filePath - Path to file
 */
export function getFileStatsSync(filePath: string): fs.Stats {
  try {
    return fs.statSync(filePath);
  } catch (error) {
    const fsError = error as NodeJS.ErrnoException;
    throw new FilesystemError(
      `Failed to get file stats: ${fsError.message}`,
      fsError.code ?? 'UNKNOWN',
      filePath
    );
  }
}

/**
 * Check if path is a directory
 * @param targetPath - Path to check
 */
export async function isDirectory(targetPath: string): Promise<boolean> {
  try {
    const stats = await fsStat(targetPath);
    return stats.isDirectory();
  } catch {
    return false;
  }
}

/**
 * Check if path is a directory (synchronous)
 * @param targetPath - Path to check
 */
export function isDirectorySync(targetPath: string): boolean {
  try {
    const stats = fs.statSync(targetPath);
    return stats.isDirectory();
  } catch {
    return false;
  }
}

/**
 * Check if path is a file
 * @param targetPath - Path to check
 */
export async function isFile(targetPath: string): Promise<boolean> {
  try {
    const stats = await fsStat(targetPath);
    return stats.isFile();
  } catch {
    return false;
  }
}

/**
 * Check if path is a file (synchronous)
 * @param targetPath - Path to check
 */
export function isFileSync(targetPath: string): boolean {
  try {
    const stats = fs.statSync(targetPath);
    return stats.isFile();
  } catch {
    return false;
  }
}

// ============================================
// JSON File Operations
// ============================================

/**
 * Read and parse a JSON file
 * @param filePath - Path to JSON file
 */
export async function readJsonFile<T>(filePath: string): Promise<T> {
  const content = await readFile(filePath);
  try {
    return JSON.parse(content) as T;
  } catch (error) {
    throw new FilesystemError(
      `Failed to parse JSON: ${(error as Error).message}`,
      'PARSE_ERROR',
      filePath
    );
  }
}

/**
 * Read and parse a JSON file (synchronous)
 * @param filePath - Path to JSON file
 */
export function readJsonFileSync<T>(filePath: string): T {
  const content = readFileSync(filePath);
  try {
    return JSON.parse(content) as T;
  } catch (error) {
    throw new FilesystemError(
      `Failed to parse JSON: ${(error as Error).message}`,
      'PARSE_ERROR',
      filePath
    );
  }
}

/**
 * Write data to a JSON file
 * @param filePath - Path to JSON file
 * @param data - Data to write
 * @param pretty - Whether to format with indentation
 */
export async function writeJsonFile<T>(filePath: string, data: T, pretty = true): Promise<void> {
  const content = pretty ? JSON.stringify(data, null, 2) : JSON.stringify(data);
  await writeFile(filePath, content);
}

/**
 * Write data to a JSON file (synchronous)
 * @param filePath - Path to JSON file
 * @param data - Data to write
 * @param pretty - Whether to format with indentation
 */
export function writeJsonFileSync<T>(filePath: string, data: T, pretty = true): void {
  const content = pretty ? JSON.stringify(data, null, 2) : JSON.stringify(data);
  writeFileSync(filePath, content);
}

// ============================================
// Base64 Operations
// ============================================

/**
 * Read a file and convert to base64
 * @param filePath - Path to file
 */
export async function readFileAsBase64(filePath: string): Promise<string> {
  const buffer = await readFileBuffer(filePath);
  return buffer.toString('base64');
}

/**
 * Read a file and convert to base64 (synchronous)
 * @param filePath - Path to file
 */
export function readFileAsBase64Sync(filePath: string): string {
  const buffer = readFileBufferSync(filePath);
  return buffer.toString('base64');
}

// ============================================
// Path Utilities
// ============================================

/**
 * Get the hosts file path for the current OS
 */
export function getHostsFilePath(): string {
  const platform = process.platform;

  switch (platform) {
    case 'win32':
      return path.join(
        process.env['SystemRoot'] ?? 'C:\\Windows',
        'System32',
        'drivers',
        'etc',
        'hosts'
      );
    case 'darwin':
    case 'linux':
      return '/etc/hosts';
    default:
      throw new Error(`Unsupported platform: ${platform}`);
  }
}

/**
 * Normalize a path for the current OS
 * @param targetPath - Path to normalize
 */
export function normalizePath(targetPath: string): string {
  return path.normalize(targetPath);
}

/**
 * Join path segments
 * @param segments - Path segments to join
 */
export function joinPath(...segments: string[]): string {
  return path.join(...segments);
}

/**
 * Get the directory name from a path
 * @param filePath - File path
 */
export function getDirname(filePath: string): string {
  return path.dirname(filePath);
}

/**
 * Get the file name from a path
 * @param filePath - File path
 * @param ext - Extension to remove (optional)
 */
export function getBasename(filePath: string, ext?: string): string {
  return path.basename(filePath, ext);
}

/**
 * Get the extension from a path
 * @param filePath - File path
 */
export function getExtname(filePath: string): string {
  return path.extname(filePath);
}

/**
 * Logger Module
 *
 * Centralized logging functionality with support for different log levels,
 * timestamps, and structured context.
 */

/**
 * Log levels in order of severity
 */
export enum LogLevel {
  DEBUG = 'debug',
  INFO = 'info',
  WARN = 'warn',
  ERROR = 'error',
}

/**
 * Log level numeric values for comparison
 */
const LOG_LEVEL_VALUES: Record<LogLevel, number> = {
  [LogLevel.DEBUG]: 0,
  [LogLevel.INFO]: 1,
  [LogLevel.WARN]: 2,
  [LogLevel.ERROR]: 3,
};

/**
 * Logger configuration options
 */
export interface LoggerConfig {
  /** Minimum log level to output */
  level?: LogLevel;
  /** Whether to include timestamps */
  timestamps?: boolean;
  /** Custom prefix for log messages */
  prefix?: string;
  /** Whether to log to file (future implementation) */
  logToFile?: boolean;
  /** Path to log file (if logToFile is true) */
  logFilePath?: string;
}

/**
 * Logger interface for dependency injection
 */
export interface ILogger {
  debug(message: string, context?: Record<string, unknown>): void;
  info(message: string, context?: Record<string, unknown>): void;
  warn(message: string, context?: Record<string, unknown>): void;
  error(message: string, error?: Error | null, context?: Record<string, unknown>): void;
}

/**
 * Format a date as a human-readable timestamp
 */
function formatTimestamp(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const hours = String(date.getHours()).padStart(2, '0');
  const minutes = String(date.getMinutes()).padStart(2, '0');
  const seconds = String(date.getSeconds()).padStart(2, '0');

  return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

/**
 * Format context object for logging
 */
function formatContext(context: Record<string, unknown>): string {
  try {
    return JSON.stringify(context);
  } catch {
    return '[Unable to stringify context]';
  }
}

/**
 * Logger class
 *
 * Provides structured logging with configurable levels and formatting.
 */
export class Logger implements ILogger {
  private static instance: Logger | null = null;
  private readonly config: Required<LoggerConfig>;

  constructor(config: LoggerConfig = {}) {
    this.config = {
      level: config.level ?? LogLevel.INFO,
      timestamps: config.timestamps ?? true,
      prefix: config.prefix ?? '',
      logToFile: config.logToFile ?? false,
      logFilePath: config.logFilePath ?? '',
    };
  }

  /**
   * Get or create the singleton logger instance
   */
  static getInstance(config?: LoggerConfig): Logger {
    Logger.instance ??= new Logger(config);
    return Logger.instance;
  }

  /**
   * Reset the singleton instance (for testing)
   */
  static resetInstance(): void {
    Logger.instance = null;
  }

  /**
   * Check if a log level should be output
   */
  private shouldLog(level: LogLevel): boolean {
    return LOG_LEVEL_VALUES[level] >= LOG_LEVEL_VALUES[this.config.level];
  }

  /**
   * Build the log message
   */
  private buildMessage(
    level: LogLevel,
    message: string,
    context?: Record<string, unknown>
  ): string {
    const parts: string[] = [];

    if (this.config.timestamps) {
      parts.push(`[${formatTimestamp(new Date())}]`);
    }

    parts.push(`[${level.toUpperCase()}]`);

    if (this.config.prefix !== '') {
      parts.push(`[${this.config.prefix}]`);
    }

    parts.push(message);

    if (context !== undefined && Object.keys(context).length > 0) {
      parts.push(formatContext(context));
    }

    return parts.join(' ');
  }

  /**
   * Log a debug message
   */
  debug(message: string, context?: Record<string, unknown>): void {
    if (!this.shouldLog(LogLevel.DEBUG)) {
      return;
    }

    const formattedMessage = this.buildMessage(LogLevel.DEBUG, message, context);
    console.debug(formattedMessage);
  }

  /**
   * Log an info message
   */
  info(message: string, context?: Record<string, unknown>): void {
    if (!this.shouldLog(LogLevel.INFO)) {
      return;
    }

    const formattedMessage = this.buildMessage(LogLevel.INFO, message, context);
    console.info(formattedMessage);
  }

  /**
   * Log a warning message
   */
  warn(message: string, context?: Record<string, unknown>): void {
    if (!this.shouldLog(LogLevel.WARN)) {
      return;
    }

    const formattedMessage = this.buildMessage(LogLevel.WARN, message, context);
    console.warn(formattedMessage);
  }

  /**
   * Log an error message with optional error object
   */
  error(message: string, error?: Error | null, context?: Record<string, unknown>): void {
    if (!this.shouldLog(LogLevel.ERROR)) {
      return;
    }

    const formattedMessage = this.buildMessage(LogLevel.ERROR, message, context);
    console.error(formattedMessage);

    if (error !== null && error !== undefined) {
      if (error.stack !== undefined) {
        console.error(error.stack);
      } else if (error.message !== undefined) {
        console.error(`Error: ${error.message}`);
      }
    }
  }

  /**
   * Create a child logger with a prefix
   */
  child(prefix: string): Logger {
    const combinedPrefix = this.config.prefix !== '' ? `${this.config.prefix}:${prefix}` : prefix;

    return new Logger({
      ...this.config,
      prefix: combinedPrefix,
    });
  }
}

/**
 * Legacy function for backwards compatibility
 * @deprecated Use Logger class instead
 */
export function logDebugMessageToConsole(
  message: string | null,
  error: Error | null | undefined,
  stackTrace: string | null | undefined
): void {
  const date = new Date();
  const humanReadableTimestamp = formatTimestamp(date);

  let errorMessage = `<message: ${message ?? 'null'}, date: ${humanReadableTimestamp}>`;

  if (error !== null && error !== undefined) {
    if (error.stack !== undefined) {
      errorMessage += `\n${error.stack}`;
    }
  }

  if (stackTrace !== null && stackTrace !== undefined) {
    errorMessage += `\n${stackTrace}`;
  }

  console.log(errorMessage);
}

/**
 * Create a new logger instance
 */
export function createLogger(config?: LoggerConfig): Logger {
  return new Logger(config);
}

/**
 * Get the default logger instance
 */
export function getLogger(): Logger {
  return Logger.getInstance();
}

/**
 * S3 Storage Client
 *
 * AWS S3 compatible storage client for managing video files.
 * Supports listing, fetching, and streaming objects.
 */

import {
  S3Client,
  ListObjectsV2Command,
  GetObjectCommand,
  PutObjectCommand,
  DeleteObjectCommand,
  DeleteObjectsCommand,
  HeadObjectCommand,
  type S3ClientConfig,
  type _Object,
} from '@aws-sdk/client-s3';
import type { Readable } from 'stream';
import type { ILogger } from './logger.js';

/**
 * S3 storage error
 */
export class S3StorageError extends Error {
  constructor(
    message: string,
    public readonly code?: string,
    public readonly operation?: string
  ) {
    super(message);
    this.name = 'S3StorageError';
  }
}

/**
 * S3 storage client configuration
 */
export interface S3StorageClientConfig {
  /** AWS access key ID */
  accessKeyId: string;
  /** AWS secret access key */
  secretAccessKey: string;
  /** S3 endpoint URL (for S3-compatible services) */
  endpoint?: string;
  /** AWS region */
  region?: string;
  /** Force path style (required for some S3-compatible services) */
  forcePathStyle?: boolean;
  /** Optional logger */
  logger?: ILogger;
}

/**
 * S3 object info
 */
export interface S3ObjectInfo {
  key: string;
  size?: number | undefined;
  lastModified?: Date | undefined;
  etag?: string | undefined;
}

/**
 * S3 list result
 */
export interface S3ListResult {
  objects: S3ObjectInfo[];
  isTruncated: boolean;
  continuationToken?: string | undefined;
}

/**
 * S3 upload options
 */
export interface S3UploadOptions {
  contentType?: string;
  cacheControl?: string;
  metadata?: Record<string, string>;
}

/**
 * S3 Storage Client
 *
 * Handles all S3 storage operations for video files.
 */
export class S3StorageClient {
  private readonly client: S3Client;
  private readonly logger: ILogger | undefined;

  constructor(config: S3StorageClientConfig) {
    this.logger = config.logger;

    const s3Config: S3ClientConfig = {
      credentials: {
        accessKeyId: config.accessKeyId,
        secretAccessKey: config.secretAccessKey,
      },
      region: config.region ?? 'us-east-1',
    };

    if (config.endpoint !== undefined && config.endpoint !== '') {
      s3Config.endpoint = config.endpoint;
    }

    if (config.forcePathStyle !== undefined) {
      s3Config.forcePathStyle = config.forcePathStyle;
    }

    this.client = new S3Client(s3Config);
  }

  // ============================================
  // List Operations
  // ============================================

  /**
   * List objects with a prefix
   * @param bucket - S3 bucket name
   * @param prefix - Object key prefix
   * @param maxKeys - Maximum number of keys to return
   * @param continuationToken - Continuation token for pagination
   */
  async listObjectsWithPrefix(
    bucket: string,
    prefix: string,
    maxKeys = 1000,
    continuationToken?: string
  ): Promise<S3ListResult> {
    try {
      const command = new ListObjectsV2Command({
        Bucket: bucket,
        Prefix: prefix,
        MaxKeys: maxKeys,
        ContinuationToken: continuationToken,
      });

      const response = await this.client.send(command);

      const objects: S3ObjectInfo[] = (response.Contents ?? []).map((obj: _Object) => ({
        key: obj.Key ?? '',
        size: obj.Size,
        lastModified: obj.LastModified,
        etag: obj.ETag,
      }));

      return {
        objects,
        isTruncated: response.IsTruncated ?? false,
        continuationToken: response.NextContinuationToken,
      };
    } catch (error) {
      this.logger?.error('Failed to list objects', error as Error, {
        bucket,
        prefix,
      });
      throw new S3StorageError(
        `Failed to list objects: ${(error as Error).message}`,
        undefined,
        'listObjectsWithPrefix'
      );
    }
  }

  /**
   * List all objects with a prefix (handles pagination)
   * @param bucket - S3 bucket name
   * @param prefix - Object key prefix
   */
  async listAllObjectsWithPrefix(bucket: string, prefix: string): Promise<S3ObjectInfo[]> {
    const allObjects: S3ObjectInfo[] = [];
    let continuationToken: string | undefined;

    do {
      const result = await this.listObjectsWithPrefix(bucket, prefix, 1000, continuationToken);
      allObjects.push(...result.objects);
      continuationToken = result.continuationToken;
    } while (continuationToken !== undefined && continuationToken !== '');

    return allObjects;
  }

  // ============================================
  // Get Operations
  // ============================================

  /**
   * Get object as buffer
   * @param bucket - S3 bucket name
   * @param key - Object key
   */
  async getObjectBuffer(bucket: string, key: string): Promise<Buffer> {
    try {
      const command = new GetObjectCommand({
        Bucket: bucket,
        Key: key,
      });

      const response = await this.client.send(command);
      const stream = response.Body as Readable;

      return await this.streamToBuffer(stream);
    } catch (error) {
      this.logger?.error('Failed to get object', error as Error, {
        bucket,
        key,
      });
      throw new S3StorageError(
        `Failed to get object: ${(error as Error).message}`,
        undefined,
        'getObjectBuffer'
      );
    }
  }

  /**
   * Get object as stream
   * @param bucket - S3 bucket name
   * @param key - Object key
   */
  async getObjectStream(bucket: string, key: string): Promise<Readable> {
    try {
      const command = new GetObjectCommand({
        Bucket: bucket,
        Key: key,
      });

      const response = await this.client.send(command);
      return response.Body as Readable;
    } catch (error) {
      this.logger?.error('Failed to get object stream', error as Error, {
        bucket,
        key,
      });
      throw new S3StorageError(
        `Failed to get object stream: ${(error as Error).message}`,
        undefined,
        'getObjectStream'
      );
    }
  }

  /**
   * Check if object exists
   * @param bucket - S3 bucket name
   * @param key - Object key
   */
  async objectExists(bucket: string, key: string): Promise<boolean> {
    try {
      const command = new HeadObjectCommand({
        Bucket: bucket,
        Key: key,
      });

      await this.client.send(command);
      return true;
    } catch {
      return false;
    }
  }

  /**
   * Get object metadata
   * @param bucket - S3 bucket name
   * @param key - Object key
   */
  async getObjectMetadata(bucket: string, key: string): Promise<S3ObjectInfo | null> {
    try {
      const command = new HeadObjectCommand({
        Bucket: bucket,
        Key: key,
      });

      const response = await this.client.send(command);
      return {
        key,
        size: response.ContentLength,
        lastModified: response.LastModified,
        etag: response.ETag,
      };
    } catch {
      return null;
    }
  }

  // ============================================
  // Put Operations
  // ============================================

  /**
   * Upload buffer to S3
   * @param bucket - S3 bucket name
   * @param key - Object key
   * @param data - Buffer data
   * @param options - Upload options
   */
  async putObject(
    bucket: string,
    key: string,
    data: Buffer | Readable,
    options?: S3UploadOptions
  ): Promise<void> {
    try {
      const command = new PutObjectCommand({
        Bucket: bucket,
        Key: key,
        Body: data,
        ContentType: options?.contentType,
        CacheControl: options?.cacheControl,
        Metadata: options?.metadata,
      });

      await this.client.send(command);
      this.logger?.debug(`Uploaded object: ${bucket}/${key}`);
    } catch (error) {
      this.logger?.error('Failed to put object', error as Error, {
        bucket,
        key,
      });
      throw new S3StorageError(
        `Failed to put object: ${(error as Error).message}`,
        undefined,
        'putObject'
      );
    }
  }

  // ============================================
  // Delete Operations
  // ============================================

  /**
   * Delete a single object
   * @param bucket - S3 bucket name
   * @param key - Object key
   */
  async deleteObject(bucket: string, key: string): Promise<void> {
    try {
      const command = new DeleteObjectCommand({
        Bucket: bucket,
        Key: key,
      });

      await this.client.send(command);
      this.logger?.debug(`Deleted object: ${bucket}/${key}`);
    } catch (error) {
      this.logger?.error('Failed to delete object', error as Error, {
        bucket,
        key,
      });
      throw new S3StorageError(
        `Failed to delete object: ${(error as Error).message}`,
        undefined,
        'deleteObject'
      );
    }
  }

  /**
   * Delete multiple objects
   * @param bucket - S3 bucket name
   * @param keys - Object keys to delete
   */
  async deleteObjects(bucket: string, keys: string[]): Promise<void> {
    if (keys.length === 0) {
      return;
    }

    try {
      // S3 limits batch delete to 1000 objects
      const batches = this.chunkArray(keys, 1000);

      for (const batch of batches) {
        const command = new DeleteObjectsCommand({
          Bucket: bucket,
          Delete: {
            Objects: batch.map((key) => ({ Key: key })),
          },
        });

        await this.client.send(command);
      }

      this.logger?.debug(`Deleted ${keys.length} objects from ${bucket}`);
    } catch (error) {
      this.logger?.error('Failed to delete objects', error as Error, {
        bucket,
        count: keys.length,
      });
      throw new S3StorageError(
        `Failed to delete objects: ${(error as Error).message}`,
        undefined,
        'deleteObjects'
      );
    }
  }

  /**
   * Delete all objects with a prefix
   * @param bucket - S3 bucket name
   * @param prefix - Object key prefix
   */
  async deleteObjectsWithPrefix(bucket: string, prefix: string): Promise<number> {
    const objects = await this.listAllObjectsWithPrefix(bucket, prefix);
    const keys = objects.map((obj) => obj.key);

    if (keys.length > 0) {
      await this.deleteObjects(bucket, keys);
    }

    return keys.length;
  }

  // ============================================
  // Utility Methods
  // ============================================

  /**
   * Convert stream to buffer
   */
  private async streamToBuffer(stream: Readable): Promise<Buffer> {
    return new Promise((resolve, reject) => {
      const chunks: Buffer[] = [];

      stream.on('data', (chunk: Buffer) => {
        chunks.push(chunk);
      });

      stream.on('end', () => {
        resolve(Buffer.concat(chunks));
      });

      stream.on('error', (error) => {
        reject(error);
      });
    });
  }

  /**
   * Chunk array into smaller arrays
   */
  private chunkArray<T>(array: T[], size: number): T[][] {
    const chunks: T[][] = [];
    for (let i = 0; i < array.length; i += size) {
      chunks.push(array.slice(i, i + size));
    }
    return chunks;
  }

  /**
   * Destroy the client (cleanup)
   */
  destroy(): void {
    this.client.destroy();
  }
}

/**
 * Create an S3 storage client
 */
export function createS3StorageClient(config: S3StorageClientConfig): S3StorageClient {
  return new S3StorageClient(config);
}

/**
 * Echo Handler
 *
 * Handles generic echo/broadcast events for admin-initiated
 * broadcasts to all connected clients.
 */

import type {
  ExtendedWebSocket,
  IncomingWebSocketMessage,
  EchoMessage,
} from '../../types/websocket.js';
import { WebSocketHandler, type HandlerContext } from './base.js';

/**
 * Handler for echo/broadcast events
 */
export class EchoHandler extends WebSocketHandler {
  readonly name = 'EchoHandler';

  /**
   * Check if this is an echo event
   */
  canHandle(message: IncomingWebSocketMessage): boolean {
    return message.eventName === 'echo';
  }

  /**
   * Handle echo/broadcast events
   */
  handle(
    client: ExtendedWebSocket,
    message: IncomingWebSocketMessage,
    context: HandlerContext
  ): void {
    // Only authenticated/admin clients can send echo broadcasts
    if (client.socketType !== 'admin' && client.isAuthenticated !== true) {
      context.log.warn('Unauthorized echo attempt', { clientId: client.clientId });
      return;
    }

    const echoMessage = message as unknown as EchoMessage;

    if (!echoMessage.data?.eventName) {
      context.log.warn('Invalid echo message format', { clientId: client.clientId });
      return;
    }

    context.log.debug('Broadcasting echo message', {
      eventName: echoMessage.data.eventName,
    });

    // Broadcast to all clients
    context.broadcast(echoMessage);
  }
}

/**
 * WebSocket Manager
 *
 * Central manager for WebSocket connections and message routing.
 * Coordinates message handlers and provides broadcast capabilities.
 */

import type { WebSocket as WsWebSocket } from 'ws';
import type {
  ExtendedWebSocket,
  WebSocketMessage,
  IncomingWebSocketMessage,
  WebSocketClientType,
  BroadcastOptions,
  LiveStreamWatchingCounts,
} from '../types/websocket.js';
import type { HandlerContext, WebSocketHandler } from './handlers/base.js';
import { ChatMessageHandler } from './handlers/chat.js';
import { LiveStreamHandler } from './handlers/stream.js';
import { VideoStatusHandler } from './handlers/video-status.js';
import { EchoHandler } from './handlers/echo.js';
import { Logger, type ILogger } from '../utils/logger.js';

/**
 * Logger interface for the WebSocket manager
 */
export type WebSocketLogger = ILogger;

/**
 * Configuration options for WebSocket Manager
 */
export interface WebSocketManagerOptions {
  /** Logger instance */
  logger?: WebSocketLogger;
  /** Heartbeat interval in milliseconds (0 to disable) */
  heartbeatInterval?: number;
  /** Client timeout in milliseconds */
  clientTimeout?: number;
}

/**
 * Default logger using Logger class with WebSocket prefix
 */
const defaultLogger: WebSocketLogger = new Logger({ prefix: 'WS' });

/**
 * WebSocket connection manager
 *
 * Manages WebSocket clients, routes messages to handlers,
 * and provides broadcast functionality.
 */
export class WebSocketManager {
  private readonly handlers: WebSocketHandler[] = [];
  private readonly clients: Set<ExtendedWebSocket> = new Set();
  private readonly logger: WebSocketLogger;
  private readonly heartbeatInterval: number;
  private readonly clientTimeout: number;
  private heartbeatTimer: NodeJS.Timeout | null = null;
  private clientIdCounter = 0;

  constructor(options: WebSocketManagerOptions = {}) {
    this.logger = options.logger ?? defaultLogger;
    this.heartbeatInterval = options.heartbeatInterval ?? 30000;
    this.clientTimeout = options.clientTimeout ?? 60000;

    // Register default handlers
    this.registerDefaultHandlers();
  }

  /**
   * Register default message handlers
   */
  private registerDefaultHandlers(): void {
    this.registerHandler(new ChatMessageHandler());
    this.registerHandler(new LiveStreamHandler());
    this.registerHandler(new VideoStatusHandler());
    this.registerHandler(new EchoHandler());
  }

  /**
   * Register a message handler
   */
  registerHandler(handler: WebSocketHandler): void {
    this.handlers.push(handler);
    this.logger.debug(`Registered handler: ${handler.name}`);
  }

  /**
   * Start the heartbeat timer
   */
  startHeartbeat(): void {
    if (this.heartbeatInterval <= 0) {
      return;
    }

    this.heartbeatTimer = setInterval(() => {
      this.checkClientHealth();
    }, this.heartbeatInterval);
  }

  /**
   * Stop the heartbeat timer
   */
  stopHeartbeat(): void {
    if (this.heartbeatTimer !== null) {
      clearInterval(this.heartbeatTimer);
      this.heartbeatTimer = null;
    }
  }

  /**
   * Check client health and remove stale connections
   */
  private checkClientHealth(): void {
    const now = Date.now();
    const staleClients: ExtendedWebSocket[] = [];

    for (const client of this.clients) {
      if (client.lastActivity !== undefined && now - client.lastActivity > this.clientTimeout) {
        staleClients.push(client);
      }
    }

    for (const client of staleClients) {
      this.logger.warn('Removing stale client', { clientId: client.clientId });
      this.removeClient(client);
      client.close(1000, 'Connection timeout');
    }
  }

  /**
   * Add a new client connection
   */
  addClient(
    ws: WsWebSocket,
    clientType: WebSocketClientType = 'viewer',
    isAuthenticated = false
  ): ExtendedWebSocket {
    const client = ws as ExtendedWebSocket;

    // Assign client metadata
    client.clientId = `client_${++this.clientIdCounter}_${Date.now()}`;
    client.socketType = clientType;
    client.isAuthenticated = isAuthenticated;
    client.lastActivity = Date.now();

    this.clients.add(client);

    this.logger.debug('Client connected', {
      clientId: client.clientId,
      type: clientType,
    });

    // Notify handlers of new connection
    const context = this.createHandlerContext();
    for (const handler of this.handlers) {
      if (handler.onConnect !== undefined) {
        void Promise.resolve(handler.onConnect(client, context)).catch((error: unknown) => {
          this.logger.error(`Handler ${handler.name} onConnect error`, error as Error);
        });
      }
    }

    return client;
  }

  /**
   * Remove a client connection
   */
  removeClient(client: ExtendedWebSocket): void {
    if (!this.clients.has(client)) {
      return;
    }

    this.clients.delete(client);

    this.logger.debug('Client disconnected', {
      clientId: client.clientId,
    });

    // Notify handlers of disconnection
    const context = this.createHandlerContext();
    for (const handler of this.handlers) {
      if (handler.onDisconnect !== undefined) {
        void Promise.resolve(handler.onDisconnect(client, context)).catch((error: unknown) => {
          this.logger.error(`Handler ${handler.name} onDisconnect error`, error as Error);
        });
      }
    }
  }

  /**
   * Handle incoming WebSocket message
   */
  handleMessage(client: ExtendedWebSocket, rawMessage: string | Buffer): void {
    // Update activity timestamp
    client.lastActivity = Date.now();

    let message: IncomingWebSocketMessage;

    try {
      const messageStr = typeof rawMessage === 'string' ? rawMessage : rawMessage.toString('utf-8');
      message = JSON.parse(messageStr) as IncomingWebSocketMessage;
    } catch {
      this.logger.warn('Failed to parse WebSocket message', {
        clientId: client.clientId,
      });
      return;
    }

    if (!message.eventName) {
      this.logger.warn('Message missing eventName', { clientId: client.clientId });
      return;
    }

    // Find and execute handler
    const context = this.createHandlerContext();
    let handled = false;

    for (const handler of this.handlers) {
      if (handler.canHandle(message)) {
        handled = true;
        try {
          void Promise.resolve(handler.handle(client, message, context)).catch((error: unknown) => {
            this.logger.error(`Handler ${handler.name} error`, error as Error, {
              eventName: message.eventName,
            });
          });
        } catch (error) {
          this.logger.error(`Handler ${handler.name} sync error`, error as Error, {
            eventName: message.eventName,
          });
        }
        break; // Only one handler per message
      }
    }

    if (!handled) {
      this.logger.debug('No handler for message', { eventName: message.eventName });
    }
  }

  /**
   * Check if client should receive the broadcast based on filter options
   */
  private shouldReceiveBroadcast(client: ExtendedWebSocket, options?: BroadcastOptions): boolean {
    // Skip if not open
    if (client.readyState !== 1) {
      return false;
    }

    if (options === undefined) {
      return true;
    }

    // Video ID filter
    if (options.videoId !== undefined && client.videoId !== options.videoId) {
      return false;
    }

    // Client type filter
    if (options.clientTypes !== undefined && !options.clientTypes.includes(client.socketType)) {
      return false;
    }

    // Exclude specific clients
    if (
      options.excludeClients !== undefined &&
      client.clientId !== undefined &&
      options.excludeClients.includes(client.clientId)
    ) {
      return false;
    }

    return true;
  }

  /**
   * Broadcast message to clients
   */
  broadcast(message: WebSocketMessage, options?: BroadcastOptions): void {
    const messageStr = JSON.stringify(message);

    for (const client of this.clients) {
      if (!this.shouldReceiveBroadcast(client, options)) {
        continue;
      }

      try {
        client.send(messageStr);
      } catch (error) {
        this.logger.error('Failed to send message to client', error as Error, {
          clientId: client.clientId,
        });
      }
    }
  }

  /**
   * Broadcast to clients watching a specific video
   */
  broadcastToVideo(videoId: string, message: WebSocketMessage): void {
    this.broadcast(message, { videoId });
  }

  /**
   * Broadcast to admin clients
   */
  broadcastToAdmins(message: WebSocketMessage): void {
    for (const client of this.clients) {
      if (
        client.readyState === 1 &&
        (client.socketType === 'admin' || client.isAuthenticated === true)
      ) {
        try {
          client.send(JSON.stringify(message));
        } catch (error) {
          this.logger.error('Failed to send to admin', error as Error);
        }
      }
    }
  }

  /**
   * Send message to a specific client
   */
  sendTo(client: ExtendedWebSocket, message: WebSocketMessage): void {
    if (client.readyState !== 1) {
      return;
    }

    try {
      client.send(JSON.stringify(message));
    } catch (error) {
      this.logger.error('Failed to send message', error as Error, {
        clientId: client.clientId,
      });
    }
  }

  /**
   * Get live stream watching counts
   */
  getLiveStreamWatchingCounts(): LiveStreamWatchingCounts {
    const counts: LiveStreamWatchingCounts = {};

    for (const client of this.clients) {
      if (client.socketType === 'node_peer' && client.videoId !== undefined) {
        const videoId = client.videoId;
        counts[videoId] = (counts[videoId] ?? 0) + 1;
      }
    }

    return counts;
  }

  /**
   * Get connected client count
   */
  getClientCount(): number {
    return this.clients.size;
  }

  /**
   * Get all connected clients
   */
  getClients(): Set<ExtendedWebSocket> {
    return this.clients;
  }

  /**
   * Close all client connections
   */
  closeAll(code = 1001, reason = 'Server shutting down'): void {
    for (const client of this.clients) {
      try {
        client.close(code, reason);
      } catch {
        // Ignore close errors
      }
    }
    this.clients.clear();
    this.stopHeartbeat();
  }

  /**
   * Create handler context
   */
  private createHandlerContext(): HandlerContext {
    return {
      broadcast: (message, videoId): void => {
        if (videoId !== undefined) {
          this.broadcastToVideo(videoId, message);
        } else {
          this.broadcast(message);
        }
      },
      sendTo: (client, message): void => {
        this.sendTo(client, message);
      },
      getClients: (): Set<ExtendedWebSocket> => this.clients,
      log: this.logger,
    };
  }
}
